/* Vragenbank PA-toets, Wft Schadeverzekering Zakelijk. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["schade-zakelijk"] = [
["Welke volgorde past bij een systematische zakelijke risico-inventarisatie?", [["Risico's in kaart brengen, analyseren op kans en impact en dan een maatregel kiezen.", "Eerst moet duidelijk zijn welke risico's er zijn en hoe zwaar ze wegen; pas dan kun je kiezen tussen vermijden, verminderen, overdragen of zelf dragen."], ["Eerst het premiebudget vaststellen en daarna bekijken welke risico's daarbinnen passen.", "Het budget is een randvoorwaarde, maar het startpunt is het risicoprofiel van het bedrijf; anders blijven grote risico's mogelijk onbelicht."], ["Alle denkbare risico's verzekeren en na een schade bekijken welke dekkingen overbodig waren.", "Dat is geen inventarisatie maar het omgekeerde ervan; het leidt tot onnodige premie en mogelijk toch tot gaten in de dekking."], ["Alleen de risico's uitwerken die de ondernemer zelf in het intakegesprek noemt.", "De adviseur moet juist ook risico's signaleren die de ondernemer niet ziet; de klant kent zijn eigen blinde vlekken niet."]]],
["Een ondernemer heeft elk jaar een paar kleine glasschades van enkele honderden euro's. Welke risicobeheersing ligt het meest voor de hand?", [["Het risico grotendeels zelf dragen, bijvoorbeeld via een hoger eigen risico.", "Kleine, voorspelbare schaden betaalt de ondernemer via de premie toch zelf, vermeerderd met de kosten van de verzekeraar; zelf dragen is dan vaak doelmatiger."], ["Het risico volledig verzekeren, zonder eigen risico en met een zo ruim mogelijke dekking.", "Bij frequente kleine schaden betaalt de ondernemer die schaden plus kosten en marge terug in de premie; dat is zelden efficiënt."], ["Het risico vermijden door het bedrijfspand te verlaten.", "Vermijden is hier volstrekt disproportioneel; het bedrijf zou zijn activiteiten moeten opgeven voor een beperkt risico."], ["Het risico rechtstreeks overdragen aan een herverzekeraar die kleine schaden afhandelt.", "Een herverzekeraar verzekert verzekeraars, niet individuele ondernemers; dat is geen keuze die de ondernemer zelf kan maken."]]],
["Welk risico komt bij uitstek in aanmerking om via een verzekering over te dragen?", [["Een risico met een kleine kans maar een zeer grote, continuïteitsbedreigende schade.", "Dit soort risico's kan de onderneming niet zelf dragen, terwijl de lage kans de premie betaalbaar houdt; daarvoor is verzekeren bedoeld."], ["Een risico met een grote kans en een kleine schade, die het bedrijf goed kan opvangen.", "Zulke schaden zijn voorspelbaar en worden via de premie toch door de ondernemer betaald; zelf dragen ligt meer voor de hand."], ["Een schade die zeker optreedt, zoals normale slijtage van machines.", "Verzekeren vereist onzekerheid; een gebeurtenis die zeker plaatsvindt is geen verzekerbaar risico maar een kostenpost."], ["Een ondernemersrisico, zoals een teruglopende vraag naar de producten van het bedrijf.", "Het algemene ondernemersrisico van tegenvallende omzet is niet verzekerbaar; dat hoort bij het ondernemen zelf."]]],
["Een adviseur gebruikt bij de risico-inventarisatie een matrix van kans en impact. Hoe wordt een risico met zowel een hoge kans als een hoge impact het best benaderd?", [["Vooral met maatregelen die kans of impact verkleinen, of door het risico te vermijden.", "Een risico dat vaak én zwaar toeslaat is meestal niet of alleen tegen zeer hoge premie verzekerbaar; preventie of vermijden staat dan voorop."], ["Uitsluitend door het risico zelf te dragen en daarvoor een reserve op te bouwen.", "Zelf dragen past bij kleine, voorspelbare schaden; bij hoge impact kan het de continuïteit van het bedrijf bedreigen."], ["Door het risico te accepteren omdat het toch niet te beheersen is.", "Juist dit soort risico's vraagt actief beheer; accepteren zonder maatregelen is onverantwoord."], ["Door het te verzekeren met een zo laag mogelijk eigen risico en een ruime verzekerde som.", "Een verzekeraar zal een risico met hoge kans en hoge impact niet of alleen tegen een zeer hoge premie accepteren; verzekeren is hier niet de eerste stap."]]],
["Wat is het belangrijkste doel van een bedrijfsbezoek bij de risico-inventarisatie van een productiebedrijf?", [["Zien hoe het bedrijf feitelijk werkt: bouwaard, preventie en afhankelijkheden.", "Ter plaatse ziet de adviseur risico's zoals brandcompartimentering, opslag van gevaarlijke stoffen en kritieke machines, wat nodig is voor een passend advies."], ["Vaststellen welke verzekeraar voor dit bedrijf de laagste premie rekent.", "Een premievergelijking kan zonder bezoek; het bezoek dient om het risico zelf te begrijpen."], ["Controleren of de fiscale en financiële administratie van het bedrijf op orde is.", "Dat is geen taak van de schadeadviseur; voor de risico-inventarisatie gaat het om de verzekerbare risico's."], ["Vooraf afspreken hoe hoog een toekomstige schade-uitkering zal zijn.", "De uitkering hangt af van de omvang van een toekomstige schade en de polis; die kan bij een bedrijfsbezoek niet worden vastgesteld."]]],
["Wat wordt in schadeverzekeringen volgens de gangbare definitie verstaan onder brand?", [["Een vuur buiten een haard, met vlammen die zich op eigen kracht kunnen uitbreiden.", "Dit is de kern van de standaarddefinitie die verzekeraars hanteren; het gaat om een zich zelfstandig voortplantend vuur."], ["Iedere schade door hitte of vuur, waaronder ook schroeien, zengen, smelten en verkolen.", "Schroeien, zengen, smelten, verkolen en broeien zonder vlammen gelden juist niet als brand."], ["Elk vuur dat schade veroorzaakt, ook als het binnen een haard of kachel blijft.", "Vuur in een haard is een beoogd vuur en geen brand; er moet sprake zijn van vuur buiten een haard."], ["Elke gebeurtenis waarbij rook ontstaat, ook zonder vlammen.", "Rook alleen is geen brand; rook- en roetschade is wel vaak gedekt, maar als afzonderlijke gebeurtenis."]]],
["In een restaurant schroeit een te heet strijkijzer een tafelkleed, zonder dat er vlammen ontstaan. Is dit brandschade in de zin van de brandverzekering?", [["Nee, schroeien zonder vlammen valt niet onder het begrip brand.", "Zonder vlammen die zich op eigen kracht kunnen uitbreiden is er geen brand; schroeischade valt daarbuiten."], ["Ja, want de schade is door hitte ontstaan.", "Hitte alleen is onvoldoende; de definitie vraagt om vuur met vlammen buiten een haard."], ["Ja, mits de schade hoger is dan het eigen risico.", "Het eigen risico bepaalt alleen hoeveel er wordt uitgekeerd, niet of een gebeurtenis als brand geldt."], ["Nee, omdat een restaurant met open keuken een verhoogd brandrisico heeft.", "De aard van het bedrijf beïnvloedt premie en acceptatie, maar niet de vraag of schroeien brand is."]]],
["Een ondernemer huurt een winkelpand en heeft voor eigen rekening een nieuwe pui en een vaste winkelinrichting laten aanbrengen. Hoe verzekert hij dit belang het best?", [["Via een dekking voor huurdersbelang, meestal op de inventaris- of bedrijfsmiddelenpolis.", "De verbeteringen zijn voor rekening van de huurder; de huurdersbelangdekking is precies voor dit risico bedoeld."], ["Niet apart, omdat aanpassingen van de huurder altijd op de opstalpolis van de verhuurder zijn meeverzekerd.", "Dat is niet vanzelfsprekend; de verhuurder verzekert zijn eigen belang en de huurder loopt dan het risico onverzekerd te zijn."], ["Via zijn aansprakelijkheidsverzekering voor bedrijven.", "De AVB dekt aansprakelijkheid tegenover derden, geen schade aan eigen investeringen."], ["Via een bedrijfsschadeverzekering.", "Bedrijfsschade dekt het verlies aan brutowinst na een schade, niet de materiële schade aan de inrichting."]]],
["Op welke waarde wordt een bedrijfspand bij een opstalverzekering in de regel verzekerd als het na een schade wordt herbouwd?", [["De herbouwwaarde.", "De herbouwwaarde is het bedrag dat nodig is om het pand direct na de schade in dezelfde vorm en voor hetzelfde gebruik te herbouwen."], ["De WOZ-waarde.", "De WOZ-waarde is een fiscale waarde inclusief grond en sluit niet aan bij de kosten van herbouw."], ["De marktwaarde inclusief grond.", "Grond gaat bij brand niet verloren en de marktwaarde volgt de vastgoedmarkt, niet de bouwkosten."], ["De boekwaarde volgens de jaarrekening.", "De boekwaarde is na afschrijving vaak veel lager dan de herbouwkosten en zou tot een tekort leiden."]]],
["Op welke waarde worden handelsgoederen (voorraad) bij een goederenverzekering in de regel verzekerd?", [["De vervangingswaarde: wat opnieuw inkopen of maken van de goederen kost.", "De verzekering vergoedt het materiële verlies; de gemiste winstmarge valt onder een bedrijfsschadeverzekering."], ["De verkoopprijs, inclusief de winstmarge die op de goederen zou zijn gemaakt.", "Dan zou de verzekering ook winst vergoeden die niet is gemaakt; dat verlies hoort bij bedrijfsschade."], ["De fiscale boekwaarde van de voorraad na afschrijving.", "Voorraad wordt niet op die manier afgeschreven en de boekwaarde zegt weinig over de kosten van vervanging."], ["De gemiddelde waarde van de voorraad over het afgelopen jaar.", "Een gemiddelde zegt niets over de waarde op het moment van de schade en kan tot onderverzekering leiden."]]],
["Een tuincentrum heeft in het voorjaar een veel grotere voorraad dan in de winter. Welke oplossing voorkomt onderverzekering in de piek zonder het hele jaar op het piekbedrag te verzekeren?", [["Een seizoens- of piekdekking, of verzekering van de voorraad op declaratiebasis.", "Daarmee volgt de verzekerde som de werkelijke voorraad; de premie wordt afgestemd op de feitelijke waarde gedurende het jaar."], ["Verzekeren op het jaargemiddelde van de voorraad.", "In de piekperiode ligt de waarde dan boven de verzekerde som, waardoor onderverzekering kan worden toegepast."], ["Verzekeren op de laagste voorraadstand en bij een schade het verschil met de piek bijbetalen.", "Na een schade kan de dekking niet met terugwerkende kracht worden verhoogd; de onderverzekering is dan een feit."], ["De voorraad onderbrengen op de opstalpolis van het pand.", "De opstalpolis dekt het gebouw, niet de roerende zaken zoals voorraad die erin liggen."]]],
["Welke van de volgende vormen hoort bij de zes vormen van molest uit de gangbare Verbondsdefinitie?", [["Binnenlandse onlusten.", "Molest omvat gewapend conflict, burgeroorlog, opstand, binnenlandse onlusten, oproer en muiterij."], ["Terrorisme.", "Terrorisme is geen vorm van molest; voor terrorismeschade geldt een afzonderlijke regeling met de NHT."], ["Overstroming door een dijkdoorbraak.", "Overstroming is een natuurrisico en geen molest; het kent een eigen uitsluiting of dekking."], ["Een grootschalige cyberaanval.", "Een cyberaanval is geen van de zes molestvormen; cyber wordt in polissen afzonderlijk geregeld."]]],
["Hoe is terrorismeschade bij Nederlandse schadeverzekeringen doorgaans geregeld?", [["Gedekt via een terrorismeclausule met de NHT, waarbij de uitkering beperkt kan worden.", "Verzekeraars hebben dit risico samen herverzekerd bij de Nederlandse Herverzekeringsmaatschappij voor Terrorismeschaden; bij een grote ramp kan de uitkering naar verhouding worden beperkt."], ["Volledig uitgesloten op alle zakelijke polissen, net als molest en atoomkernreacties, zonder uitzondering.", "Terrorisme is juist binnen de grenzen van de clausule meeverzekerd; een volledige uitsluiting is niet de standaard."], ["Gedekt door de overheid via de Wet tegemoetkoming schade bij rampen.", "De WTS is bedoeld voor niet redelijkerwijs verzekerbare rampschade en vervangt de terrorismedekking via de NHT niet."], ["Onbeperkt gedekt, zonder enig voorbehoud over de omvang van de uitkering.", "De terrorismeclausule bevat juist een voorbehoud: de NHT kan bij grote schadelast een uitkeringspercentage vaststellen."]]],
["Een inventarispolis bevat als voorwaarde dat een inbraakalarm met doormelding aanwezig en ingeschakeld moet zijn. Na een inbraak blijkt het alarm uit te staan. Wat is juist?", [["De verzekeraar kan zich op de preventievoorwaarde beroepen en de dekking weigeren of beperken.", "Preventievoorwaarden zijn contractuele afspraken; of het beroep slaagt hangt af van de formulering en de redelijkheid, maar het risico van weigering is reëel."], ["Er zijn geen gevolgen, want preventie-eisen in een polis zijn slechts vrijblijvende aanbevelingen.", "Preventie-eisen in de polis zijn bindende voorwaarden en geen vrijblijvende adviezen."], ["De verzekeraar moet altijd volledig uitkeren, omdat inbraak op de polis een gedekt evenement is.", "Dat een evenement gedekt is, betekent niet dat de dekking geldt als de verzekerde zich niet aan de voorwaarden houdt."], ["De verzekering eindigt automatisch met terugwerkende kracht tot de oorspronkelijke ingangsdatum.", "Het gevolg is geen automatische ontbinding met terugwerkende kracht; het gaat om de dekking voor deze schade."]]],
["Wat wordt bij een bedrijfsschadeverzekering doorgaans verstaan onder brutowinst?", [["Omzet minus variabele kosten, ofwel vaste kosten plus nettowinst.", "Bij stilstand vallen de variabele kosten weg; de vaste kosten lopen door en de winst gaat verloren. Die som is het verzekerde belang."], ["Omzet minus alle kosten, inclusief de vaste kosten van het bedrijf.", "Dat is de nettowinst; de vaste kosten die bij stilstand doorlopen zouden dan buiten de dekking vallen."], ["De totale omzet van het bedrijf, inclusief de btw.", "Omzet bevat ook variabele kosten die bij stilstand niet worden gemaakt; vergoeding daarvan zou de ondernemer verrijken."], ["De nettowinst vermeerderd met de vennootschapsbelasting.", "Dat is de winst vóór belasting en laat de doorlopende vaste kosten buiten beschouwing."]]],
["Wat is de uitkeringstermijn bij een bedrijfsschadeverzekering?", [["De periode na de schadedatum waarover de verzekeraar het verlies aan brutowinst vergoedt.", "Binnen deze termijn moet het bedrijf weer op het oude niveau zijn; verlies daarna valt buiten de dekking."], ["De termijn waarbinnen de verzekeraar na een schademelding het vastgestelde schadebedrag moet betalen.", "Dat is een betalingstermijn; de uitkeringstermijn gaat over de periode waarover het verlies wordt vergoed."], ["De contractstermijn waarvoor de verzekering is gesloten.", "De looptijd van de polis staat los van de periode waarover na een schade bedrijfsschade wordt vergoed."], ["De wachttijd waarin het bedrijfsverlies voor rekening van de ondernemer blijft.", "Dat is een eigen risico in tijd; de uitkeringstermijn is de periode van vergoeding."]]],
["Een machinefabriek heeft na een brand naar verwachting achttien maanden nodig om met nieuw te bouwen machines weer volledig te produceren. De bedrijfsschadepolis heeft een uitkeringstermijn van 52 weken. Wat is het gevolg?", [["Het verlies na de 52 weken wordt niet vergoed, terwijl de bedrijfsschade dan nog doorloopt.", "De uitkeringstermijn is te kort gekozen voor de hersteltijd; de adviseur had een langere termijn moeten overwegen."], ["De verzekeraar verlengt de uitkeringstermijn automatisch tot het bedrijf hersteld is.", "De uitkeringstermijn is een contractuele grens; een automatische verlenging is geen standaard."], ["De uitkeringstermijn begint pas te lopen als de nieuwe machines zijn geleverd.", "De termijn begint in de regel op de schadedatum, niet op het moment van herstel."], ["De verzekeraar vergoedt binnen de 52 weken alsnog het volledige verlies over alle achttien maanden.", "De verzekeraar vergoedt alleen het verlies dat binnen de uitkeringstermijn wordt geleden."]]],
["Wat is bij een traditionele bedrijfsschadeverzekering doorgaans een voorwaarde voor dekking?", [["De stilstand is het gevolg van materiële schade door een gedekte gebeurtenis, zoals brand.", "Bedrijfsschade is gekoppeld aan een materiële schade die onder de polis valt; zonder die oorzaak is er geen dekking."], ["Elke omzetdaling die het bedrijf lijdt, ook als die door minder vraag wordt veroorzaakt.", "Teruglopende vraag is ondernemersrisico en valt niet onder een bedrijfsschadeverzekering."], ["De ondernemer heeft geen personeel in dienst dat tijdens de stilstand moet worden doorbetaald.", "Personeelskosten horen juist vaak bij de doorlopende vaste kosten die worden vergoed."], ["De stilstand duurt langer dan de uitkeringstermijn.", "De uitkeringstermijn is de maximale vergoedingsperiode, geen minimale duur van de stilstand."]]],
["Een bakkerij betrekt al haar meel van één molen. De molen brandt af en de bakkerij kan wekenlang niet bakken. Welke dekking had deze schade kunnen opvangen?", [["Een afhankelijkheidsdekking bij leveranciers.", "Deze uitbreiding vergoedt het verlies aan brutowinst als de stilstand wordt veroorzaakt door schade bij een bedrijf waarvan de verzekerde afhankelijk is."], ["Een huurdersbelangdekking op de inventarispolis.", "Huurdersbelang dekt verbeteringen van een huurder aan een gehuurd pand, niet schade door uitval van een leverancier."], ["Een aansprakelijkheidsverzekering voor bedrijven (AVB).", "De AVB dekt aansprakelijkheid tegenover derden, niet eigen omzetverlies door schade bij een leverancier."], ["Een productaansprakelijkheidsdekking op de AVB.", "Productaansprakelijkheid gaat over schade door gebrekkige producten bij derden, niet over leveringsproblemen."]]],
["Een accountantskantoor wil na een brand vooral direct op een andere locatie doorwerken, ook als dat extra huur en kosten met zich meebrengt. Welke dekking sluit hier het best op aan?", [["Een meerkostenverzekering.", "Een meerkostenverzekering vergoedt de extra kosten die nodig zijn om de bedrijfsvoering na een schade zo veel mogelijk voort te zetten."], ["Een opstalverzekering op herbouwwaarde.", "Die dekt het herstel van het gebouw, niet de kosten van tijdelijk elders werken."], ["Een rechtsbijstandverzekering.", "Rechtsbijstand helpt bij juridische geschillen en vergoedt geen tijdelijke huisvesting."], ["Een aansprakelijkheidsverzekering met opzichtdekking.", "Opzicht gaat over schade aan zaken van derden onder de hoede van de verzekerde, niet over eigen extra kosten."]]],
["Waarom is het belangrijk dat de verzekerde brutowinst bij een bedrijfsschadeverzekering regelmatig wordt geactualiseerd?", [["Omdat bij een te lage verzekerde brutowinst onderverzekering kan gelden.", "Groeit het bedrijf, dan dekt de oude som het verlies niet meer volledig en wordt de uitkering mogelijk naar verhouding verlaagd."], ["Omdat de uitkeringstermijn bij een verouderde opgave automatisch korter wordt.", "De uitkeringstermijn is een vaste afspraak en hangt niet af van de hoogte van de opgegeven brutowinst."], ["Omdat de verzekeraar de polis bij een verouderde opgave automatisch beëindigt.", "Een verouderde opgave leidt niet tot beëindiging; het risico zit in een te lage uitkering."], ["Omdat de hoogte van de brutowinst bepaalt hoeveel wachtdagen er gelden.", "De wachttijd is een afzonderlijke afspraak in de polis en staat los van de verzekerde brutowinst."]]],
["Welke schade is op een aansprakelijkheidsverzekering voor bedrijven (AVB) in de regel gedekt?", [["Personen- en zaakschade van derden, inclusief de gevolgschade daarvan.", "De AVB is gericht op letsel en schade aan zaken van derden, inclusief de schade die daaruit voortvloeit."], ["Zuivere vermogensschade van klanten door een onjuist of onvolledig advies.", "Schade zonder letsel of zaakschade valt doorgaans buiten de AVB; daarvoor is een beroepsaansprakelijkheidsverzekering bedoeld."], ["Schade aan de eigen inventaris en voorraad van het verzekerde bedrijf.", "Eigen schade valt onder een inventaris- of goederenverzekering; de AVB dekt schade bij derden."], ["Contractuele boetes die het bedrijf aan zijn klanten verschuldigd is.", "Boetes en verplichtingen die alleen uit een contract voortvloeien zijn op een AVB in de regel uitgesloten."]]],
["Een installateur beschadigt bij het repareren van een cv-ketel de ketel zelf. Waarom is deze schade op de AVB vaak niet of maar beperkt gedekt?", [["Vanwege de opzichtclausule voor zaken waaraan de verzekerde werkt.", "Schade aan zaken die de verzekerde onder zich heeft of waaraan hij werkt, is uitgesloten of beperkt meeverzekerd; verzekeraars willen het kwaliteitsrisico van het eigen werk niet dekken."], ["Omdat installatiebedrijven niet verzekerbaar zijn voor aansprakelijkheid.", "Installateurs kunnen prima een AVB sluiten; het gaat hier om een specifieke uitsluiting."], ["Omdat het om personenschade gaat, die buiten de AVB valt.", "Het gaat hier om zaakschade; personenschade is op een AVB juist een kerndekking."], ["Omdat de AVB alleen schade buiten de werkzaamheden dekt.", "De AVB dekt juist de aansprakelijkheid uit de bedrijfsuitoefening, dus ook tijdens het werk."]]],
["Welke vorm van aansprakelijkheid geldt volgens het BW voor de producent van een gebrekkig product?", [["Risicoaansprakelijkheid: schuld van de producent hoeft niet te worden aangetoond.", "De productaansprakelijkheidsregeling in het BW legt de aansprakelijkheid bij de producent, ongeacht verwijtbaarheid."], ["Schuldaansprakelijkheid: de benadeelde moet verwijtbaar handelen van de producent aantonen.", "Juist het schuldvereiste is bij productaansprakelijkheid losgelaten om de benadeelde te beschermen."], ["Uitsluitend contractuele aansprakelijkheid tegenover de directe koper van het product.", "De regeling geldt ook tegenover benadeelden zonder contract met de producent, zoals gebruikers en omstanders."], ["Aansprakelijkheid alleen als de producent opzettelijk heeft gehandeld.", "Opzet is geen vereiste; de producent is ook zonder enige schuld aansprakelijk voor een gebrekkig product."]]],
["Een voedselproducent ontdekt dat een partij besmet is en haalt alle producten uit de winkels. Zijn de terugroepkosten gedekt op een standaard AVB?", [["Doorgaans niet; daarvoor is een afzonderlijke terugroepkostenverzekering nodig.", "Standaard AVB-polissen sluiten terugroepkosten in de regel uit; dit risico wordt apart verzekerd."], ["Ja, terugroepkosten vallen op een AVB altijd onder de productaansprakelijkheidsdekking.", "Productaansprakelijkheid dekt schade bij derden; de kosten van het terughalen van producten zijn meestal uitgesloten."], ["Ja, maar alleen als een rechter het terugroepen heeft bevolen.", "Een rechterlijk bevel maakt terugroepkosten niet gedekt als de polis ze uitsluit."], ["Nee, deze kosten vallen standaard onder de bedrijfsschadeverzekering.", "Bedrijfsschade vereist meestal materiële schade door een gedekte gebeurtenis; terugroepkosten zijn daar geen standaarddekking."]]],
["Binnen welke termijnen kan een benadeelde een producent aanspreken op grond van de productaansprakelijkheidsregeling in het BW?", [["Verjaring drie jaar na bekendheid met schade, gebrek en producent; verval tien jaar na het in het verkeer brengen.", "Deze combinatie van verjarings- en vervaltermijn komt uit de Europese productaansprakelijkheidsrichtlijn en staat in het BW."], ["Verjaring vijf jaar na bekendheid met schade en aansprakelijke; verval twintig jaar na de schadeveroorzakende gebeurtenis.", "Dit zijn de algemene termijnen bij schadevergoeding; voor productaansprakelijkheid gelden kortere termijnen."], ["Verjaring één jaar na bekendheid met schade en producent; verval vijf jaar na aankoop van het product.", "Deze termijnen zijn te kort en sluiten niet aan bij de wettelijke regeling."], ["Verjaring twee jaar na het ontstaan van de schade; een vervaltermijn bestaat bij producten niet.", "Er geldt wel degelijk een vervaltermijn, zodat de producent na verloop van tijd zekerheid heeft."]]],
["Een werknemer raakt gewond tijdens zijn werk. Wat moet de werkgever volgens het BW in beginsel aantonen om niet aansprakelijk te zijn?", [["Dat hij zijn zorgplicht is nagekomen, of dat er opzet of bewuste roekeloosheid van de werknemer was.", "De bewijslast ligt bij de werkgever; lichte onvoorzichtigheid van de werknemer ontslaat hem niet van aansprakelijkheid."], ["Niets; de gewonde werknemer moet bewijzen dat de werkgever verwijtbaar tekort is geschoten.", "Bij werkgeversaansprakelijkheid is de bewijslast omgekeerd; de werkgever moet aantonen dat hij voldoende heeft gedaan."], ["Dat de werknemer zelf licht onvoorzichtig was bij het uitvoeren van het werk.", "Gewone onvoorzichtigheid van de werknemer komt voor rekening van de werkgever; alleen opzet of bewuste roekeloosheid telt."], ["Dat hij een passende aansprakelijkheidsverzekering voor bedrijven heeft afgesloten en de premie betaald.", "Een verzekering zegt niets over de aansprakelijkheid zelf; zij financiert alleen de gevolgen."]]],
["Een bouwbedrijf laat werk uitvoeren door een ingehuurde zzp'er, die op de bouwplaats gewond raakt door een ondeugdelijke steiger. Wat is juist?", [["Het bouwbedrijf kan net als een werkgever aansprakelijk zijn voor de veiligheid van de werkplek.", "Het BW breidt de werkgeversaansprakelijkheid uit tot wie in zijn bedrijf arbeid laat verrichten door niet-werknemers; de AVB moet dit risico dan ook dekken."], ["Het bouwbedrijf is nooit aansprakelijk, want een zzp'er draagt altijd zelf zijn eigen ongevalsrisico.", "Dat is te stellig; de zorgplicht voor een veilige werkplek kan ook tegenover ingehuurde krachten gelden."], ["Het bouwbedrijf is alleen aansprakelijk als de zzp'er een schijnzelfstandige blijkt.", "Ook zonder arbeidsovereenkomst kan de opdrachtgever op grond van de verruimde werkgeversaansprakelijkheid aansprakelijk zijn."], ["Alleen de leverancier van de steiger kan voor deze schade aansprakelijk zijn.", "De leverancier kan aansprakelijk zijn, maar dat sluit aansprakelijkheid van het bouwbedrijf voor de werkplek niet uit."]]],
["Een werknemer krijgt tijdens een zakelijke rit met zijn eigen auto buiten zijn schuld een ongeval; de veroorzaker is onbekend. Op welke grond kan de werkgever toch aansprakelijk zijn voor de schade?", [["Op grond van goed werkgeverschap, omdat hij moet zorgen voor een behoorlijke verzekering.", "Volgens vaste rechtspraak moet de werkgever voor een passende verzekering zorgen; ontbreekt die, dan kan hij zelf voor de schade opdraaien."], ["Op grond van de WAM-polis van de werkgever, die ook auto's van werknemers dekt.", "Een WAM-polis van de werkgever dekt alleen de daarop verzekerde voertuigen en vergoedt geen schade van de eigen bestuurder."], ["Op grond van de productaansprakelijkheid van de werkgever voor de door de werknemer gebruikte auto.", "Productaansprakelijkheid gaat over gebrekkige producten en heeft hier geen betekenis."], ["Niet, want bij een rit in een eigen auto is de werkgever nooit aansprakelijk.", "Juist bij zakelijke ritten kan de werkgever op grond van goed werkgeverschap aansprakelijk zijn, ook in een eigen auto."]]],
["Welke schade dekt een beroepsaansprakelijkheidsverzekering typisch, die op een AVB meestal buiten de dekking valt?", [["Zuivere vermogensschade van een opdrachtgever door een beroepsfout.", "Beroepsbeoefenaren als adviseurs, accountants en architecten veroorzaken vooral financiële schade zonder letsel of zaakschade; daarvoor is deze verzekering bedoeld."], ["Letselschade van een bezoeker die op kantoor uitglijdt over een natte vloer.", "Dat is personenschade van een derde en valt onder de AVB."], ["Schade aan de eigen kantoorinventaris door een gesprongen waterleiding.", "Eigen schade valt onder een inventarisverzekering, niet onder een aansprakelijkheidsverzekering."], ["Schade aan de eigen bedrijfsauto na een aanrijding op weg naar een klant.", "Schade aan een eigen voertuig valt onder een cascodekking van de autoverzekering."]]],
["Een beroepsaansprakelijkheidsverzekering is gesloten op claims-made-basis. Wat betekent dat?", [["Gedekt zijn aanspraken die tijdens de looptijd worden ingesteld en gemeld, binnen de inloopregeling.", "Bepalend is het moment van de aanspraak, niet het moment van de fout; daarom zijn inloop- en uitloopregelingen belangrijk bij wisselen of stoppen."], ["De dekking geldt voor fouten tijdens de looptijd, ook als de claim pas jaren na beëindiging wordt ingediend.", "Dat beschrijft een dekking op basis van het moment van de gebeurtenis; bij claims-made is het moment van de aanspraak bepalend."], ["Het eigen risico geldt per claim in plaats van per gebeurtenis.", "Claims-made zegt iets over de tijdsafbakening van de dekking, niet over de toepassing van het eigen risico."], ["De verzekeraar keert alleen uit als de opdrachtgever een procedure bij de rechter begint.", "Ook een schriftelijke aansprakelijkstelling buiten rechte geldt als aanspraak; een procedure is niet vereist."]]],
["Een medewerker van een schoonmaakbedrijf stoot tijdens het werk bij een klant per ongeluk een kostbaar beeld om. Wie is tegenover de klant in beginsel aansprakelijk?", [["De werkgever, die aansprakelijk is voor fouten van zijn werknemers.", "Een werkgever is aansprakelijk voor fouten van werknemers die in het kader van hun werk worden gemaakt; de klant kan het bedrijf aanspreken."], ["Uitsluitend de medewerker die het beeld persoonlijk heeft omgestoten.", "De klant kan de werkgever aanspreken; werknemers worden tegenover de werkgever bovendien beschermd tegen regres, behoudens opzet of bewuste roekeloosheid."], ["Niemand, omdat het om een ongeluk zonder opzet ging.", "Een onrechtmatige daad vereist geen opzet; een onvoorzichtige handeling tijdens het werk kan voldoende zijn."], ["De klant zelf, omdat hij het beeld niet veilig had weggezet.", "Eigen schuld van de klant kan hooguit een rol spelen bij de verdeling, maar maakt de klant niet in beginsel zelf aansprakelijk."]]],
["Wie is bij een bestuurdersaansprakelijkheidsverzekering (D&O) doorgaans verzekeringnemer en wie zijn de verzekerden?", [["De vennootschap is verzekeringnemer; bestuurders en commissarissen zijn verzekerden.", "De rechtspersoon sluit en betaalt de polis, maar die dekt de persoonlijke aansprakelijkheid van de bestuurders en toezichthouders."], ["Elke bestuurder is zelf verzekeringnemer en de vennootschap is de verzekerde partij.", "De D&O-polis dekt juist de persoonlijke aansprakelijkheid van bestuurders, niet primair de vennootschap."], ["De aandeelhouders zijn verzekerden voor het verlies op hun belegging in de vennootschap.", "Aandeelhouders zijn juist vaak de partij die bestuurders aanspreekt; hun beleggingsrisico is niet verzekerd."], ["Alle werknemers zijn verzekerd voor fouten in hun werk.", "De D&O richt zich op bestuurders en toezichthouders; werknemers vallen hier in beginsel niet onder."]]],
["Een curator spreekt de bestuurders van een failliete bv aan omdat de jaarrekening te laat is gedeponeerd in de drie jaar voor het faillissement. Wat is het gevolg?", [["Onbehoorlijk bestuur staat vast en wordt vermoed een belangrijke oorzaak van het faillissement te zijn.", "Schending van de publicatieplicht geeft een vaststaand onbehoorlijk bestuur en een weerlegbaar vermoeden van oorzakelijk verband."], ["Er zijn geen gevolgen, omdat te laat deponeren slechts een administratieve fout is.", "De wet verbindt aan het niet nakomen van de publicatieplicht juist ingrijpende gevolgen in faillissement (een onbelangrijk verzuim daargelaten)."], ["De bestuurder krijgt alleen een bestuurlijke boete en is niet civiel aansprakelijk.", "Het gaat hier om civiele aansprakelijkheid tegenover de boedel, niet om een boete."], ["De bestuurder is hoofdelijk aansprakelijk voor het hele tekort en kan op geen enkele wijze nog tegenbewijs leveren.", "Het vermoeden dat het onbehoorlijk bestuur een belangrijke oorzaak is van het faillissement, kan de bestuurder weerleggen."]]],
["Wanneer is een bestuurder volgens vaste rechtspraak intern aansprakelijk tegenover de vennootschap wegens onbehoorlijke taakvervulling?", [["Als hem een ernstig verwijt kan worden gemaakt.", "De Hoge Raad legt de lat hoog om bestuurders ruimte te geven voor ondernemerschap; een gewone fout is niet genoeg."], ["Bij iedere fout die tot schade leidt.", "Dan zou besturen onwerkbaar worden; de maatstaf is een ernstig verwijt."], ["Alleen na een strafrechtelijke veroordeling.", "Civiele aansprakelijkheid vereist geen strafrechtelijke veroordeling."], ["Alleen als alle aandeelhouders daarmee unaniem instemmen.", "De aansprakelijkheid volgt uit de wet en de rechtspraak, niet uit instemming van aandeelhouders."]]],
["Welke kosten vormen een kernonderdeel van de D&O-verzekering, ook als de aanspraak uiteindelijk ongegrond blijkt?", [["De kosten van verweer en juridische bijstand van de bestuurder.", "Juist bij claims tegen bestuurders lopen de verweerkosten snel op; de D&O vergoedt die ook als de bestuurder uiteindelijk niet aansprakelijk is."], ["De bestuurlijke boetes die aan de vennootschap zijn opgelegd.", "Boetes zijn in de regel niet of slechts beperkt verzekerbaar en betreffen hier de vennootschap zelf."], ["Het omzetverlies van de vennootschap door de claim.", "Bedrijfsverlies van de vennootschap valt buiten de D&O, die de persoonlijke aansprakelijkheid van bestuurders dekt."], ["De doorbetaling van het salaris van de bestuurder tijdens de procedure.", "Inkomensderving van de bestuurder is geen onderdeel van de D&O-dekking."]]],
["Welke uitsluiting is in een D&O-polis gebruikelijk?", [["Schade door opzet of fraude van de bestuurder, als die vaststaat.", "Ook het bewust genieten van onrechtmatig voordeel is vaak uitgesloten; tot opzet of fraude bij uitspraak of erkenning vaststaat, worden verweerkosten vaak wel voorgeschoten."], ["Elke claim die een curator na het faillissement tegen bestuurders indient.", "Claims van curatoren zijn juist een belangrijk risico waarvoor de D&O bedoeld is."], ["Claims die zijn gebaseerd op onbehoorlijke taakvervulling door het bestuur.", "Onbehoorlijke taakvervulling is juist de kern van de bestuurdersaansprakelijkheid en dus van de dekking."], ["Alle kosten van juridisch verweer die een bestuurder maakt.", "Verweerkosten zijn een kerndekking van de D&O, geen uitsluiting."]]],
["Welke twee onderdelen vormen de kern van een Construction All Risks-verzekering (CAR)?", [["Schade aan het werk in uitvoering en aansprakelijkheid tegenover derden.", "De CAR dekt het bouwproject zelf en de aansprakelijkheid die uit de bouwactiviteiten voortvloeit, aangevuld met optionele rubrieken."], ["Inkomensverlies van de aannemer en verzuimkosten van zijn personeel tijdens de bouw.", "Dat zijn inkomens- en verzuimrisico's die met andere verzekeringen worden gedekt."], ["De opstal van de opdrachtgever na oplevering en glasbreuk.", "Na oplevering is het gebouw een opstalrisico van de eigenaar; de CAR gaat over de bouwfase."], ["Het vervoer van bouwmaterialen en de CMR-aansprakelijkheid van de vervoerder.", "Transportrisico's en vervoerdersaansprakelijkheid vallen onder transportverzekeringen."]]],
["Wie zijn op een projectgebonden CAR-verzekering doorgaans gezamenlijk verzekerd?", [["Opdrachtgever, hoofdaannemer en onderaannemers, vaak ook ontwerpers.", "Een gezamenlijke verzekering voorkomt discussie en verhaal tussen bouwpartners; wie precies verzekerd is, staat in de polis."], ["Alleen de opdrachtgever, omdat die het project laat uitvoeren.", "De CAR is juist bedoeld om alle betrokken bouwpartijen onder één polis te brengen."], ["Alleen de hoofdaannemer; onderaannemers zijn nooit meeverzekerd.", "Onderaannemers zijn op een project-CAR in de regel meeverzekerd."], ["Alleen de toekomstige huurders en gebruikers van het gebouw.", "Toekomstige gebruikers hebben geen rol in de bouwfase en zijn geen verzekerden op de CAR."]]],
["Door een ontwerpfout bezwijkt tijdens de bouw een betonvloer, waarbij ook installaties eronder worden beschadigd. Hoe gaat een CAR-polis hier doorgaans mee om?", [["Herstel van het gebrekkige onderdeel zelf is vaak uitgesloten, de gevolgschade doorgaans gedekt.", "De CAR is geen garantie voor kwaliteit, maar beschermt wel tegen de schade die een gebrek elders in het werk veroorzaakt."], ["Alle kosten, ook het opnieuw ontwerpen en aanleggen van de vloer, zijn volledig gedekt.", "Het herstel van het gebrek zelf valt doorgaans buiten de dekking; anders zou de CAR een kwaliteitsgarantie worden."], ["Niets is gedekt, omdat de oorzaak van de schade een ontwerpfout is.", "Een ontwerpfout sluit niet alle dekking uit; de gevolgschade aan andere onderdelen is in de regel gedekt."], ["Alleen de beroepsaansprakelijkheidsverzekering van de architect kan iets vergoeden.", "De BAV van de ontwerper kan een rol spelen bij verhaal, maar de CAR zelf vergoedt doorgaans de gevolgschade."]]],
["Voor wiens risico is het werk volgens de UAV 2012 in beginsel tot het moment van oplevering?", [["Voor risico van de aannemer.", "Tot de oplevering draagt de aannemer in beginsel het risico van schade aan het werk; een CAR-verzekering sluit daarop aan."], ["Voor risico van de opdrachtgever.", "Het risico gaat in beginsel pas bij oplevering over; tot dat moment ligt het bij de aannemer, behoudens uitzonderingen."], ["Voor gezamenlijk risico van aannemer en opdrachtgever, ieder voor de helft.", "De UAV kent geen standaard verdeling bij helfte; de hoofdregel legt het risico bij de aannemer."], ["Voor risico van de architect.", "De architect is ontwerper en geen partij die het risico van het werk in uitvoering draagt."]]],
["Op welk vervoer is het CMR-verdrag van toepassing?", [["Betaald internationaal wegvervoer van goederen tussen twee landen, waarvan minstens één CMR-land.", "Dit is de kern van het toepassingsgebied van het verdrag; binnenlands vervoer valt erbuiten."], ["Al het betaalde goederenvervoer over de weg, ook als het geheel binnen Nederland of de Benelux plaatsvindt.", "Binnenlands wegvervoer valt niet onder het CMR maar onder het nationale recht."], ["Internationaal goederenvervoer over zee tussen havens van verschillende landen.", "Zeevervoer kent eigen verdragen en regels; het CMR gaat over wegvervoer."], ["Uitsluitend internationale verhuizingen en het vervoer van stoffelijke overschotten.", "Deze vormen van vervoer zijn juist uitgezonderd van het CMR."]]],
["Tot welk bedrag is de aansprakelijkheid van de wegvervoerder onder het CMR in beginsel beperkt bij verlies of beschadiging van de lading?", [["8,33 rekeneenheden (SDR) per kilogram ontbrekend brutogewicht.", "Deze limiet geldt tenzij een hogere waarde of bijzonder belang is aangegeven, of er sprake is van opzet of daarmee gelijk te stellen schuld."], ["De volledige werkelijke waarde van de goederen, zonder enige limiet.", "Het CMR kent juist een limiet per kilogram; daardoor kan de ladingbelanghebbende met een tekort blijven zitten."], ["Een vast bedrag per zending, ongeacht het gewicht.", "De limiet wordt berekend per kilogram brutogewicht, niet per zending."], ["2 rekeneenheden (SDR) per kilogram ontbrekend brutogewicht.", "Een limiet in die orde kom je tegen bij zeevervoer; het CMR hanteert 8,33 SDR per kilogram."]]],
["Een exporteur vindt een transportverzekering overbodig, omdat de vervoerder een CMR-verzekering heeft. Wat is het belangrijkste tegenargument?", [["De CMR-verzekering dekt alleen de beperkte aansprakelijkheid van de vervoerder, niet de lading zelf.", "Bij schade waarvoor de vervoerder niet aansprakelijk is, of boven de limiet, krijgt de exporteur niets; een goederentransportverzekering dekt zijn eigen belang."], ["De CMR-verzekering van de vervoerder geldt alleen voor binnenlands wegvervoer.", "De CMR-verzekering dekt juist internationaal wegvervoer; het probleem zit in de beperkte aansprakelijkheid."], ["De CMR-verzekering is alleen geldig als de exporteur zelf ook verzekeringnemer is.", "De vervoerder is verzekeringnemer; daarom dekt de polis ook alleen zijn aansprakelijkheid."], ["De ontvanger is wettelijk verplicht de lading tijdens het gehele internationale vervoer zelf te verzekeren.", "Er bestaat geen algemene wettelijke verplichting voor de ontvanger; wie verzekert, volgt uit de afspraken, zoals de Incoterms."]]],
["Binnen welke termijn verjaart een vordering op grond van het CMR in de regel?", [["Eén jaar; bij opzet of gelijk te stellen schuld drie jaar.", "Het CMR kent een korte verjaringstermijn; ladingbelanghebbenden en hun verzekeraars moeten daarom snel handelen."], ["Drie jaar; bij opzet of gelijk te stellen schuld vijf jaar.", "Deze termijnen zijn langer dan het verdrag bepaalt."], ["Zes maanden; bij opzet of gelijk te stellen schuld één jaar.", "De verjaringstermijn is korter dan bij gewone vorderingen, maar niet zo kort als zes maanden."], ["Vijf jaar; bij opzet of gelijk te stellen schuld twintig jaar.", "Dit lijkt op de algemene termijnen voor schadevergoeding in het BW, niet op het CMR."]]],
["Een Nederlandse exporteur verkoopt goederen aan een koper in Azië op basis van de Incoterm CIF. Wie moet volgens deze Incoterm de transportverzekering voor de goederen sluiten?", [["De verkoper, ten behoeve van de koper, met ten minste een minimale dekking.", "Bij CIF (Cost, Insurance and Freight) zorgt de verkoper voor vracht én verzekering; het risico gaat al over bij inlading."], ["De koper, omdat het risico al bij inlading op het schip op hem overgaat.", "Het risico gaat inderdaad vroeg over, maar bij CIF is de verkoper verplicht de verzekering te regelen."], ["De vervoerder, als vast onderdeel van de vervoersovereenkomst met de verkoper.", "De vervoerder verzekert hooguit zijn eigen aansprakelijkheid, niet de goederen ten behoeve van koper of verkoper."], ["Niemand; bij CIF is een verzekering niet nodig.", "De 'I' in CIF staat juist voor de verzekeringsplicht van de verkoper."]]],
["Wat is een kenmerk van een wagenparkverzekering ten opzichte van losse autopolissen?", [["Alle voertuigen staan op één polis; de premie volgt vaak het schadeverloop van het geheel.", "In plaats van een bonus-malustrede per auto kijkt de verzekeraar naar de schadelast van het totale wagenpark."], ["Voor voertuigen op een wagenparkpolis geldt de wettelijke WAM-verzekeringsplicht niet.", "De WAM-plicht geldt voor ieder motorrijtuig dat aan het verkeer deelneemt, ook op een wagenparkpolis."], ["Een wagenparkpolis dekt uitsluitend cascoschade.", "Een wagenparkpolis bevat in elk geval de verplichte WAM-dekking, met daarnaast eventueel casco."], ["Een wagenparkpolis is alleen mogelijk voor privéauto's die werknemers voor zakelijke ritten gebruiken.", "De wagenparkpolis is juist bedoeld voor de bedrijfsvoertuigen van een onderneming."]]],
["Een werknemer rijdt onder invloed van alcohol met een bedrijfsbus en verwondt een fietser. Kan de WAM-verzekeraar de fietser tegenwerpen dat de polis rijden onder invloed uitsluit?", [["Nee; de fietser heeft een eigen recht tegen de WAM-verzekeraar, die later kan verhalen.", "De WAM beschermt het slachtoffer: de verzekeraar kan polisuitsluitingen niet aan de benadeelde tegenwerpen, maar kan na uitkering wel verhaal nemen op de verzekerde."], ["Ja; de fietser moet zijn schade dan verhalen op de werknemer persoonlijk.", "Dan zou de bescherming van verkeersslachtoffers afhangen van het gedrag van de bestuurder, wat de WAM juist voorkomt."], ["Ja; de fietser moet zich dan wenden tot het Waarborgfonds Motorverkeer.", "Het Waarborgfonds springt bij als er geen verzekering is of de veroorzaker onbekend is, niet bij een polisuitsluiting."], ["Nee, en de verzekeraar kan de uitgekeerde schade daarna ook op niemand verhalen.", "De verzekeraar keert uit aan de benadeelde, maar kan bij een uitsluiting wel verhaal nemen op de verzekerde."]]],
["Waarom is naast de WAM-dekking een schadeverzekering voor inzittenden (SVI) relevant voor een wagenpark?", [["De WAM dekt de eigen bestuurder niet; de SVI wel, ongeacht schuld.", "Voor werkgevers sluit dit aan bij de plicht als goed werkgever te zorgen voor een behoorlijke verzekering van werknemers in het verkeer."], ["De SVI is wettelijk verplicht voor elk bedrijfsvoertuig op de weg.", "Alleen de WAM is wettelijk verplicht; de SVI is een aanvullende, vrijwillige dekking."], ["De SVI dekt schade aan de lading die in bestelbussen wordt vervoerd.", "Lading valt onder een goederen- of transportverzekering, niet onder een inzittendenverzekering."], ["De SVI vervangt de cascodekking van de voertuigen in het wagenpark.", "Casco dekt schade aan het voertuig zelf; de SVI dekt schade van personen in het voertuig."]]],
["Een bedrijf met een wagenparkpolis koopt tussentijds drie nieuwe bestelbussen. Wat regelt een wagenparkpolis hierover vaak?", [["Ze zijn automatisch meeverzekerd, mits tijdig gemeld voor de premieafrekening.", "Dit voorkomt dat nieuwe voertuigen onverzekerd de weg op gaan; de premie wordt achteraf verrekend."], ["Ze zijn pas gedekt nadat voor elk voertuig een afzonderlijke polis is gesloten.", "Juist het automatisch meeverzekeren is een voordeel van een wagenparkpolis."], ["Ze kunnen pas per het volgende contractjaar aan de polis worden toegevoegd.", "Tussentijds toevoegen is gebruikelijk; anders zouden voertuigen maandenlang onverzekerd zijn."], ["Ze zijn automatisch casco verzekerd, maar nog zonder WAM-dekking.", "De WAM-dekking is het minimum dat voor ieder voertuig op de polis geldt."]]],
["Welke combinatie van dekkingen is kenmerkend voor een cyberverzekering?", [["Eigen schade (zoals dataherstel en stilstand) plus aansprakelijkheid bij een datalek.", "Een cyberpolis combineert eerstepartijschade met aansprakelijkheid en biedt vaak ook directe hulp bij een incident."], ["Alleen schade aan computers en servers door brand, water of inbraak.", "Fysieke schade aan apparatuur valt onder de inventaris- of elektronicaverzekering."], ["Alleen aansprakelijkheid tegenover klanten, zonder dekking voor eigen schade.", "Een groot deel van de cyberschade is juist eigen schade, zoals herstel en stilstand."], ["Alleen boetes die de Autoriteit Persoonsgegevens na een datalek oplegt.", "Boetes zijn hooguit beperkt en alleen voor zover wettelijk toegestaan verzekerd; ze zijn niet de kern van de dekking."]]],
["Een adviesbureau ontdekt dat bij een hack persoonsgegevens van klanten zijn buitgemaakt. Binnen welke termijn moet het datalek in de regel bij de Autoriteit Persoonsgegevens worden gemeld?", [["Zonder onredelijke vertraging en zo mogelijk binnen 72 uur na ontdekking.", "Dit volgt uit de AVG, tenzij het lek waarschijnlijk geen risico voor betrokkenen oplevert; cyberverzekeraars helpen vaak met deze melding."], ["Binnen 30 dagen na ontdekking van het lek, via het meldloket van de AP.", "Die termijn is te ruim; de AVG vraagt om melding zo mogelijk binnen 72 uur."], ["Pas in de jaarlijkse privacyrapportage van het bureau.", "Een datalek moet direct worden gemeld, niet pas achteraf in een jaarverslag."], ["Pas nadat de cyberverzekeraar daarvoor uitdrukkelijk toestemming heeft gegeven.", "De meldplicht is een wettelijke plicht van de verwerkingsverantwoordelijke en hangt niet af van de verzekeraar."]]],
["Waarom vragen cyberverzekeraars bij acceptatie vaak naar maatregelen als multifactorauthenticatie en offline back-ups?", [["Omdat ze kans en impact sterk verkleinen en dus premie en acceptatie bepalen.", "Cyberrisico hangt sterk af van basisbeveiliging; ontbreken van zulke maatregelen kan leiden tot een hogere premie, extra voorwaarden of weigering."], ["Omdat deze maatregelen voor ieder bedrijf wettelijk zijn voorgeschreven.", "Er bestaat geen algemene wettelijke plicht tot precies deze maatregelen voor alle bedrijven; het gaat om acceptatiebeleid van de verzekeraar."], ["Alleen voor statistische doeleinden; de antwoorden hebben geen invloed op de polis.", "De antwoorden hebben juist directe invloed op acceptatie, premie en voorwaarden."], ["Om de dekking voor eigen schade bij voorbaat uit te kunnen sluiten.", "De vragen dienen om het risico in te schatten, niet om de dekking uit te sluiten."]]],
["Een medewerker maakt na een vervalste e-mail van 'de directeur' een groot bedrag over naar een oplichter. Waarom is deze schade niet vanzelfsprekend gedekt op een cyberpolis?", [["Zulke fraude is vaak uitgesloten of beperkt gedekt: er is geen hack, maar een eigen betaling.", "Voor CEO-fraude en social engineering is soms een aparte module of fraudeverzekering nodig; de adviseur moet de voorwaarden nauwkeurig nalezen."], ["Deze schade valt altijd onder de aansprakelijkheidsverzekering voor bedrijven (AVB).", "De AVB dekt aansprakelijkheid voor schade bij derden, geen eigen vermogensverlies door fraude."], ["Deze schade is op elke cyberpolis zonder beperking of sublimiet gedekt.", "Dat is niet zo; veel polissen sluiten deze vorm van fraude uit of kennen een lage sublimiet."], ["De bank is wettelijk altijd verplicht zo'n frauduleuze zakelijke betaling volledig aan de klant te vergoeden.", "Een zakelijke klant die zelf een betaling autoriseert, kan zich in de regel niet op zo'n vergoedingsplicht van de bank beroepen."]]],
["Wanneer heeft een verzekerde met een rechtsbijstandverzekering op grond van de Europese regels in elk geval recht op vrije keuze van een advocaat?", [["Zodra een gerechtelijke of administratieve procedure nodig is, en bij belangenconflict.", "Volgens de Europese regels en de rechtspraak van het Hof van Justitie mag de verzekeraar de keuze van de advocaat in die situaties niet beperken."], ["Nooit; de verzekeraar bepaalt in alle gevallen zelf welke jurist of advocaat de zaak inhoudelijk behandelt.", "De vrije advocaatkeuze is juist een Europees gewaarborgd recht bij procedures en belangenconflicten."], ["Alleen als de verzekeraar daar vooraf schriftelijk mee instemt.", "Het recht op vrije keuze hangt niet af van toestemming van de verzekeraar."], ["Vanaf het eerste contact, dus ook al voor advies en minnelijke onderhandelingen.", "In de fase vóór een procedure mag de verzekeraar de zaak in beginsel door eigen juristen laten behandelen."]]],
["Een ondernemer sluit een zakelijke rechtsbijstandverzekering af omdat een conflict met een leverancier al loopt. Wat is waarschijnlijk het gevolg?", [["Geen dekking, omdat het geschil al bestond of voorzienbaar was bij het sluiten.", "Een verzekering dekt onzekere toekomstige gebeurtenissen; bestaande of te verwachten geschillen zijn uitgesloten."], ["Volledige dekking, omdat het geschil pas na de ingangsdatum bij de verzekeraar wordt gemeld.", "Bepalend is wanneer het geschil is ontstaan of voorzienbaar was, niet wanneer het wordt gemeld."], ["Dekking zodra de ondernemer het eigen risico van de polis heeft betaald.", "Een eigen risico verandert niets aan de uitsluiting van een geschil dat al bestond."], ["Dekking, mits het financiële belang onder de polisgrens blijft.", "Een minimum- of maximumbelang regelt de omvang, niet de uitsluiting van bestaande geschillen."]]],
["Waarom is de schadebehandeling van rechtsbijstand bij veel verzekeraars ondergebracht in een afzonderlijke rechtspersoon?", [["Om belangenconflicten te voorkomen; dit vloeit voort uit Europese regels.", "Bijvoorbeeld als dezelfde verzekeraar ook de tegenpartij verzekert; de Europese regels verlangen een waarborg zoals een aparte schadebehandelingsorganisatie."], ["Om fiscale redenen, omdat rechtsbijstand dan niet onder de assurantiebelasting valt.", "De afzondering heeft een toezichtrechtelijke reden: het voorkomen van belangenconflicten."], ["Omdat Kifid dat voorschrijft als voorwaarde voor aansluiting van de verzekeraar.", "Kifid is een klachteninstituut en stelt die eis niet; de regel komt uit Europese wetgeving."], ["Om de kosten en daarmee de premie voor rechtsbijstand lager te maken.", "Kostenbeheersing is niet de reden; het gaat om onafhankelijke behandeling van de zaak."]]],
["Wat bepalen veel zakelijke rechtsbijstandpolissen als het financiële belang van een geschil veel kleiner is dan de te verwachten behandelkosten?", [["De verzekeraar mag de zaak afkopen door het financiële belang te vergoeden.", "Met zo'n afkoopregeling voorkomt de verzekeraar onevenredig hoge kosten; de verzekerde krijgt dan het belang vergoed in plaats van de procedure."], ["De verzekeraar moet de zaak in dat geval altijd tot in de hoogste instantie voeren.", "Polissen kennen juist afwegingen over proportionaliteit; een onbeperkte procesplicht bestaat niet."], ["De verzekerde moet het geschil dan zelf verzekeren via de AVB.", "De AVB dekt aansprakelijkheid voor schade bij derden en geen juridische geschillen van de verzekerde zelf."], ["De dekking vervalt en de premie wordt teruggestort.", "De dekking vervalt niet; de verzekeraar kiest voor een andere manier om het belang te vergoeden."]]],
["Hoe lang is een werkgever bij ziekte van een werknemer in beginsel verplicht het loon door te betalen?", [["104 weken.", "De loondoorbetalingsplicht bij ziekte duurt in beginsel twee jaar; dit risico kan de werkgever met een verzuimverzekering afdekken."], ["52 weken.", "Na één jaar loopt de loondoorbetaling in beginsel door; de wettelijke periode is twee jaar."], ["26 weken.", "Dat is veel korter dan de wettelijke termijn van twee jaar."], ["13 weken.", "Na dertien weken moet de werkgever het verzuim melden bij het UWV, maar de loondoorbetaling loopt door tot twee jaar."]]],
["Wat dekt een verzuimverzekering voor werkgevers?", [["De loonkosten die de werkgever bij ziekte moet doorbetalen, na het eigen risico.", "Het is een schadeverzekering voor de werkgever: de verzekeraar vergoedt (een deel van) de doorbetaalde loonkosten."], ["Het inkomen van de werknemer, dat de verzekeraar rechtstreeks aan hem betaalt.", "De werknemer houdt recht op loon van de werkgever; de verzekering vergoedt de werkgever, niet de werknemer."], ["De WIA-uitkering van de werknemer na twee jaar ziekte.", "Na twee jaar gaat het om de WIA; daarvoor bestaan aparte (eigenrisicodragers)verzekeringen."], ["De transitievergoeding bij ontslag van een langdurig zieke werknemer.", "Een ontslagvergoeding is geen verzuimrisico en valt niet onder een verzuimverzekering."]]],
["Een werkgever wordt eigenrisicodrager voor de WGA. Welk risico neemt hij daarmee op zich?", [["De kosten van WGA-uitkeringen en re-integratie, voor maximaal tien jaar.", "In plaats van een gedifferentieerde premie aan het UWV draagt de werkgever zelf de WGA-lasten; dit risico kan hij verzekeren met een WGA-eigenrisicoverzekering."], ["De WW-uitkeringen van werknemers die door de werkgever worden ontslagen.", "Het eigenrisicodragerschap in deze vraag betreft de WGA, niet de werkloosheidswet."], ["De loondoorbetaling bij ziekte in de eerste twee ziektejaren.", "Die plicht heeft iedere werkgever al; eigenrisicodragerschap voor de WGA betreft de periode daarna."], ["De IVA-uitkering van volledig en duurzaam arbeidsongeschikte werknemers.", "Voor de IVA kan de werkgever geen eigenrisicodrager worden; die blijft bij het UWV."]]],
["Welke verplichting uit de Arbeidsomstandighedenwet is relevant bij de beoordeling van werkgeversaansprakelijkheid en de acceptatie van een AVB?", [["Een werkgever met personeel moet een risico-inventarisatie en -evaluatie (RI&E) hebben.", "Een ontbrekende of verouderde RI&E maakt het voor de werkgever lastig aan te tonen dat hij zijn zorgplicht is nagekomen."], ["Een werkgever moet zijn bedrijfsauto's jaarlijks laten keuren door de Arbeidsinspectie.", "Voertuigkeuringen hebben een eigen regeling en zijn geen kernverplichting uit de Arbowet."], ["Een werkgever is wettelijk verplicht een aansprakelijkheidsverzekering voor bedrijven te sluiten.", "Een AVB is voor de meeste bedrijven niet wettelijk verplicht, al is zij wel sterk aan te raden."], ["Een werkgever met personeel moet altijd een verzuimverzekering hebben afgesloten.", "Een verzuimverzekering is vrijwillig; de werkgever mag het risico van loondoorbetaling ook zelf dragen."]]],
["Wat houdt een volmacht in de schadeverzekeringsmarkt in?", [["Een verzekeraar machtigt een gevolmachtigde om namens hem risico's te accepteren.", "Vaak mag de gevolmachtigde ook polissen afgeven en schaden afhandelen; het verzekeringsrisico blijft bij de verzekeraar (de volmachtgever)."], ["De gevolmachtigde neemt het verzekeringsrisico over en draagt de schaden zelf.", "De gevolmachtigde is geen risicodrager; de verzekeraar blijft het risico dragen."], ["De klant machtigt zijn adviseur om namens hem een polis te ondertekenen.", "Dat is een machtiging van de klant aan de adviseur, niet de volmacht van een verzekeraar aan een bemiddelaar."], ["Een verzekeraar draagt een deel van zijn risico's over aan een herverzekeraar.", "Dat is herverzekering; daarbij gaat het om risicospreiding tussen verzekeraars."]]],
["Een gevolmachtigde handelt een schade af namens de verzekeraar en wijst de claim onterecht af. Wie is tegenover de verzekeringnemer gehouden de verzekeringsovereenkomst na te komen?", [["De verzekeraar, omdat de gevolmachtigde in zijn naam heeft gehandeld.", "De overeenkomst is gesloten met de verzekeraar; die blijft verantwoordelijk, ook voor werkzaamheden die hij heeft uitbesteed."], ["Alleen de gevolmachtigde, omdat die de beslissing heeft genomen.", "De gevolmachtigde is vertegenwoordiger en geen contractspartij als verzekeraar."], ["De adviseur van de verzekeringnemer.", "De adviseur heeft een eigen zorgplicht, maar is geen partij bij de verzekeringsovereenkomst."], ["Het Kifid, als de klacht daar wordt ingediend.", "Kifid beslecht geschillen, maar is geen partij die de overeenkomst moet nakomen."]]],
["Wat is een collectief contract bij schade- en verzuimverzekeringen?", [["Een raamovereenkomst waaronder leden of werknemers van een groep verzekerd zijn.", "Collectieve contracten bieden schaal: vaak gunstigere voorwaarden of premies voor de aangesloten groep."], ["Een polis waarin meerdere verzekeraars ieder voor een vast aandeel een deel van één risico dragen.", "Dat is coassurantie; een collectief contract gaat over het verzekeren van een groep."], ["Een overeenkomst waarbij een verzekeraar een deel van zijn eigen risico's herverzekert.", "Herverzekering speelt tussen verzekeraars en staat los van het collectief verzekeren van een groep."], ["Een contract dat uitsluitend voor collectieve pensioenregelingen kan worden gebruikt.", "Collectieve contracten komen ook voor bij onder meer verzuim, ongevallen en aansprakelijkheid."]]],
["Een adviseur wil een mkb-klant onderbrengen in een collectief contract van een brancheorganisatie met een aantrekkelijke collectiviteitskorting. Wat is juist?", [["De adviseur moet nog steeds nagaan of de voorwaarden passen bij de wensen en behoeften en de risico's van de klant.", "Een korting zegt niets over de passendheid van de dekking; de zorgplicht en de wensen-en-behoeftentoets blijven gelden."], ["Bij een collectief contract vervalt de zorgplicht, omdat de brancheorganisatie de voorwaarden al vooraf heeft beoordeeld.", "De brancheorganisatie adviseert de individuele klant niet; die verantwoordelijkheid ligt bij de adviseur."], ["Een collectief contract is altijd beter dan een individuele polis.", "Collectieve voorwaarden zijn standaard en sluiten niet altijd aan op het specifieke risico van de klant."], ["De adviseur hoeft alleen de premie te vergelijken met andere aanbieders.", "Passend advies gaat over dekking, uitsluitingen en voorwaarden, niet alleen over de prijs."]]],
["Wat is coassurantie?", [["Meerdere verzekeraars dragen ieder rechtstreeks een vast aandeel van hetzelfde risico.", "Bij coassurantie is elke deelnemende verzekeraar voor zijn eigen aandeel risicodrager tegenover de verzekeringnemer."], ["Een verzekeraar draagt een deel van het risico over aan een of meer herverzekeraars.", "Bij herverzekering heeft de verzekeringnemer alleen een contract met de directe verzekeraar."], ["Twee los van elkaar gesloten polissen bij verschillende verzekeraars voor hetzelfde belang.", "Dat is dubbele verzekering, die meestal niet is afgestemd; coassurantie is een bewust verdeelde plaatsing."], ["De verzekeringnemer draagt zelf een deel van iedere schade als eigen risico.", "Een eigen risico is risicobehoud door de verzekeringnemer, geen verdeling tussen verzekeraars."]]],
["Bij een coassurantiepolis gaat één van de deelnemende verzekeraars failliet. Wat betekent dit voor de verzekeringnemer?", [["De anderen betalen alleen hun eigen aandeel; het aandeel van de failliete verzekeraar niet.", "Coassuradeuren zijn niet hoofdelijk aansprakelijk; ieder is alleen gebonden voor het getekende aandeel."], ["De andere verzekeraars nemen het aandeel van de failliete verzekeraar automatisch over.", "Er is geen hoofdelijkheid; zonder bijzondere afspraak nemen de anderen dat aandeel niet over."], ["De leidende verzekeraar betaalt het volledige schadebedrag aan de verzekeringnemer.", "De leider voert het beheer, maar draagt alleen zijn eigen aandeel van het risico."], ["De polis vervalt in zijn geheel met terugwerkende kracht tot de ingangsdatum.", "De polis blijft bestaan voor de aandelen van de overige verzekeraars."]]],
["Welke rol heeft de leidende verzekeraar bij een beurspolis?", [["Hij voert namens alle deelnemers het beheer en de schadebehandeling.", "Via de leidende-verzekeraarsclausule binden zijn beslissingen de volgers, voor zover de polis dat bepaalt; de verzekeringnemer hoeft niet met elke verzekeraar apart te onderhandelen."], ["Hij draagt altijd 100% van het risico en herverzekert dat bij de volgers.", "De leider draagt alleen zijn eigen aandeel; de volgers zijn zelfstandig risicodrager voor hun aandeel."], ["Hij int alleen de premie; over schaden beslist elke verzekeraar afzonderlijk.", "De leider heeft juist een centrale rol in de schadebehandeling, binnen de grenzen van de polis."], ["Hij is de makelaar die het risico namens de klant op de beurs plaatst.", "De makelaar plaatst het risico; de leidende verzekeraar is een van de risicodragers."]]],
["Wat is voor de verzekeringnemer het belangrijkste verschil tussen coassurantie en herverzekering?", [["Bij coassurantie heeft hij een vordering op elke deelnemende verzekeraar, bij herverzekering niet op de herverzekeraar.", "De herverzekeraar heeft geen contract met de verzekeringnemer; bij coassurantie is iedere verzekeraar zijn wederpartij voor zijn aandeel."], ["Bij herverzekering heeft hij een rechtstreekse vordering op de herverzekeraar; bij coassurantie alleen op de leidende verzekeraar.", "Dit is precies omgekeerd; de herverzekeraar staat buiten de relatie met de verzekeringnemer."], ["Er is geen verschil; beide termen betekenen hetzelfde en worden door elkaar gebruikt in de markt.", "Het zijn verschillende constructies met een andere rechtspositie voor de verzekeringnemer."], ["Herverzekering is in Nederland verboden voor zakelijke risico's, coassurantie is wel toegestaan.", "Herverzekering is een normaal en toegestaan instrument voor risicospreiding tussen verzekeraars."]]],
["Waarom worden grote zakelijke risico's vaak via een makelaar op de beursmarkt geplaatst?", [["Omdat het risico zo over meerdere verzekeraars kan worden gespreid, met maatwerk.", "Eén verzekeraar heeft vaak onvoldoende capaciteit of risicobereidheid; spreiding via coassurantie lost dat op."], ["Omdat de Wft-gedragsregels op de beursmarkt nooit van toepassing zijn.", "Dat is te stellig; ook bij plaatsing via de beurs gelden regels voor bemiddeling en advies."], ["Omdat het voor één verzekeraar wettelijk verboden is een groot risico alleen te dragen.", "Zo'n verbod bestaat niet; het is een kwestie van capaciteit en risicobereidheid."], ["Omdat bij een beurspolis wettelijk nooit onderverzekering kan worden toegepast.", "Onderverzekering hangt af van de polisvoorwaarden, niet van de vraag of het een beurspolis is."]]],
["Wat houdt de mededelingsplicht van de verzekeringnemer vóór het sluiten van de verzekering in?", [["Hij moet de feiten meedelen die hij kent of behoort te kennen en die voor de verzekeraar van belang kunnen zijn.", "Dit is de kern van de precontractuele mededelingsplicht in het BW; ook feiten waarnaar niet uitdrukkelijk wordt gevraagd kunnen eronder vallen."], ["Hij hoeft alleen feiten te melden waarnaar uitdrukkelijk is gevraagd, ook als er helemaal geen vragenlijst is gebruikt.", "Zonder vragenlijst geldt de algemene mededelingsplicht; de beperking tot gestelde vragen hoort bij een vragenlijst van de verzekeraar."], ["Hij moet tijdens de gehele looptijd iedere wijziging van het risico direct aan de verzekeraar melden.", "De wettelijke mededelingsplicht ziet op de periode vóór het sluiten; meldplichten tijdens de looptijd volgen uit de polis."], ["Hij hoeft alleen feiten te melden die hij zeker weet, niet feiten die hij had behoren te kennen.", "Ook feiten die hij behoort te kennen vallen onder de plicht; onwetendheid door nalatigheid beschermt niet."]]],
["Een verzekeraar heeft voor een AVB een eigen vragenlijst gebruikt. Er is niet gevraagd naar eerdere faillissementen van de directeur. Kan de verzekeraar zich later beroepen op het niet melden daarvan?", [["Nee, tenzij het feit is verzwegen met het opzet de verzekeraar te misleiden.", "Bij een vragenlijst van de verzekeraar komt het risico van niet-gestelde vragen voor zijn rekening, behalve bij opzet tot misleiding."], ["Ja, want de verzekeringnemer moet alle relevante feiten altijd uit zichzelf melden.", "Bij gebruik van een vragenlijst is de mededelingsplicht in beginsel beperkt tot de gestelde vragen."], ["Ja, mits het feit relevant was voor de acceptatie.", "Relevantie is niet genoeg; zonder vraag kan de verzekeraar zich alleen bij opzet tot misleiding beroepen."], ["Nee, zelfs niet als met opzet tot misleiding is verzwegen.", "Opzet tot misleiding vormt juist de uitzondering; dan kan de verzekeraar zich wel beroepen op het verzwijgen."]]],
["Na een schade blijkt dat de verzekeringnemer bij het sluiten feiten niet heeft gemeld. De verzekeraar zou de verzekering dan wel hebben gesloten, maar tegen een hogere premie. Wat is het gevolg?", [["De uitkering wordt verminderd naar verhouding van de betaalde tot de verschuldigde premie.", "Het BW kiest voor proportionaliteit: de verzekerde krijgt wat bij de werkelijk betaalde premie hoort."], ["Er wordt niets uitgekeerd, omdat de verzekeringnemer zijn mededelingsplicht heeft geschonden.", "Een volledige afwijzing past bij de situatie dat de verzekeraar de verzekering helemaal niet zou hebben gesloten, of bij opzet tot misleiding."], ["Er wordt volledig uitgekeerd, omdat de verzekeraar de verzekering toch had gesloten.", "De verzekeraar zou een hogere premie hebben gevraagd; dat verschil komt tot uitdrukking in een lagere uitkering."], ["Er wordt volledig uitgekeerd, minus het premieverschil over de looptijd.", "De wet hanteert een evenredige vermindering van de uitkering, geen verrekening van het premieverschil."]]],
["Een ondernemer heeft bij het sluiten van een inventarisverzekering een eerdere inbraak niet gemeld. Later ontstaat schade door blikseminslag. Mag de verzekeraar de uitkering op grond van de verzwijging weigeren?", [["Nee; het verzwegen feit staat los van de schade, dus de verzekeraar moet in beginsel uitkeren.", "Het BW kent een causaliteitsregel: verzwijging van een feit dat niet van belang is voor het risico zoals het zich heeft verwezenlijkt, leidt niet tot vermindering, behalve bij opzet tot misleiding."], ["Ja; iedere verzwijging, ook van een niet-gerelateerd feit, geeft de verzekeraar het recht de uitkering te weigeren.", "De wet stelt grenzen aan de gevolgen van verzwijging, waaronder het vereiste van verband met de verwezenlijkte schade."], ["Ja, maar de verzekeraar mag dan alleen de helft van de schade vergoeden.", "Een vaste halvering kent de wet niet; de gevolgen hangen af van de causaliteit en van wat de verzekeraar zou hebben gedaan."], ["Nee, omdat verzwijging bij zakelijke verzekeringen nooit gevolgen heeft.", "De regels over de mededelingsplicht gelden ook bij zakelijke verzekeringen."]]],
["Binnen welke termijn na ontdekking van een schending van de mededelingsplicht moet de verzekeraar de verzekeringnemer daarop wijzen, om zich op de gevolgen te kunnen beroepen?", [["Binnen twee maanden.", "De verzekeraar moet binnen twee maanden na ontdekking op de niet-nakoming wijzen, onder vermelding van de mogelijke gevolgen; doet hij dat niet, dan kan hij zich er niet meer op beroepen."], ["Binnen veertien dagen.", "Die termijn is korter dan de wet bepaalt."], ["Binnen zes maanden.", "Die termijn is langer dan de wet bepaalt."], ["Binnen één jaar.", "De wettelijke termijn is aanzienlijk korter, zodat de verzekeringnemer snel duidelijkheid krijgt."]]],
["Een inventaris met een werkelijke waarde van € 200.000 is verzekerd voor € 150.000. Er ontstaat een schade van € 40.000. Hoeveel keert de verzekeraar uit bij toepassing van de evenredigheidsregel, zonder eigen risico?", [["€ 30.000.", "Er is voor 75% verzekerd (€ 150.000 / € 200.000), dus wordt 75% van € 40.000 vergoed."], ["€ 40.000.", "Dat zou gelden bij een verzekering op eerste risico of als de evenredigheidsregel is uitgesloten."], ["€ 0.", "Onderverzekering leidt tot een evenredige vermindering, niet tot een volledige afwijzing."], ["€ 22.500.", "Dit ontstaat als de verhouding van 75% twee keer wordt toegepast; de regel wordt maar één keer toegepast."]]],
["Wat betekent het als een inventaris 'op eerste risico' is verzekerd?", [["De schade wordt vergoed tot het verzekerde bedrag, zonder beroep op onderverzekering.", "Bij een eerste-risicoverzekering is de werkelijke waarde niet van belang zolang de schade binnen het verzekerde bedrag blijft."], ["Alleen de eerste schade in een verzekeringsjaar is gedekt; latere schaden niet.", "Eerste risico zegt niets over het aantal schaden per jaar."], ["De verzekeraar keert alleen het deel van de schade boven het eigen risico uit.", "Dat geldt bij iedere polis met een eigen risico; het begrip eerste risico gaat over onderverzekering."], ["Bij dubbele verzekering betaalt deze verzekeraar altijd als eerste uit.", "De volgorde bij samenloop wordt geregeld via samenloopbepalingen, niet via het begrip eerste risico."]]],
["Een bedrijf heeft zijn inventaris bij verzekeraar A verzekerd op eerste risico tot € 100.000 en bij verzekeraar B op tweede risico. Wanneer komt verzekeraar B aan bod?", [["Voor het deel van de schade boven het bedrag van het eerste risico.", "De tweede-risicoverzekering is een aanvullende laag boven het eerste risico, volgens de eigen voorwaarden van die polis."], ["Altijd als eerste, waarna verzekeraar A het eventuele restant betaalt.", "De volgorde is juist omgekeerd: eerst het eerste risico, daarna het tweede."], ["Bij iedere schade voor de helft, naast verzekeraar A.", "Er is geen verdeling bij helfte; elke verzekeraar dekt een eigen laag van de schade."], ["Alleen als verzekeraar A failliet is of om een andere reden niet betaalt.", "Het tweede risico is een dekkingslaag en geen vangnet voor insolventie van de eerste verzekeraar."]]],
["Een zaak is bij twee verzekeraars voor hetzelfde belang tegen hetzelfde risico verzekerd, zonder bijzondere samenloopclausules. Wat is de hoofdregel?", [["Elke verzekeraar is gehouden alsof hij de enige is, maar in totaal niet meer dan de schade.", "De verzekerde mag kiezen wie hij aanspreekt; de verzekeraars verdelen de last onderling naar verhouding, zodat het indemniteitsbeginsel overeind blijft."], ["De verzekerde kan bij beide verzekeraars de volledige schade claimen en ontvangt die dubbel.", "Een schadeverzekering mag niet leiden tot verrijking; de totale uitkering is beperkt tot de schade."], ["Alleen de verzekeraar met de oudste polis is gehouden de schade te vergoeden.", "De wet legt de last niet bij de oudste polis; elke verzekeraar is in beginsel gehouden."], ["Beide verzekeraars betalen automatisch de helft en de verzekerde mag niet kiezen.", "De verzekerde mag juist kiezen wie hij aanspreekt; de onderlinge verdeling volgt daarna."]]],
["Bij een beginnende brand zet een ondernemer zijn blusmiddelen in en laat hij een bedrijf goederen in veiligheid brengen. Hoe worden deze kosten op grond van het BW vergoed?", [["Als redelijke bereddingskosten, zo nodig ook boven de verzekerde som.", "De wet stimuleert het beperken van schade: redelijke kosten van bereddingsmaatregelen komen voor rekening van de verzekeraar, zelfs boven de verzekerde som."], ["Alleen voor zover er na de schade nog ruimte is binnen de verzekerde som.", "Juist voor bereddingskosten geldt dat ze ook boven de verzekerde som worden vergoed."], ["Niet, want het gaat om eigen kosten die de ondernemer vrijwillig heeft gemaakt.", "Het BW bepaalt dat redelijke bereddingskosten voor rekening van de verzekeraar komen."], ["Alleen als de brandweer opdracht heeft gegeven voor de maatregelen.", "Een opdracht van de brandweer is geen voorwaarde; bepalend is of de maatregelen redelijk waren om schade te voorkomen of te beperken."]]],
["De verzekeraar keert een brandschade uit die door een aannemer van de buren is veroorzaakt. Wat gebeurt er met de vordering van de verzekerde op die aannemer?", [["Die gaat over op de verzekeraar voor zover deze heeft uitgekeerd (subrogatie).", "De verzekeraar kan daarna zelf verhaal nemen op de aansprakelijke derde; de verzekerde kan niet dubbel vergoed krijgen."], ["Die blijft volledig bij de verzekerde, die dus ook de aannemer nog kan aanspreken.", "Dan zou de verzekerde dubbel worden vergoed; voor het uitgekeerde deel gaat de vordering over op de verzekeraar."], ["Die vervalt door de uitkering.", "De vordering vervalt niet, maar gaat over op de verzekeraar."], ["Die gaat over op het Waarborgfonds.", "Het Waarborgfonds Motorverkeer speelt alleen bij verkeersschade zonder verzekering of met een onbekende veroorzaker."]]],
["Een kapper met een eenmanszaak heeft weinig verzekeringskennis en vraagt advies over zijn bedrijfsverzekeringen. Wat betekent dit voor de zorgplicht van de adviseur?", [["Hoe minder deskundig de klant, hoe actiever de adviseur moet waarschuwen.", "De zorgplicht is afhankelijk van de omstandigheden; bij een niet-professionele zakelijke klant reikt die verder dan bij een professionele inkoper."], ["Een zakelijke klant geldt altijd als professioneel, zodat de zorgplicht niet geldt.", "Ook bij zakelijke klanten geldt een zorgplicht; een kleine ondernemer is lang niet altijd deskundig."], ["De adviseur hoeft alleen te antwoorden op vragen die de klant zelf stelt.", "De adviseur moet ook uit zichzelf relevante risico's signaleren die de klant niet kent."], ["Toezending van de polisvoorwaarden is voldoende om aan de zorgplicht te voldoen.", "Voorwaarden toesturen vervangt geen uitleg; de adviseur moet belangrijke beperkingen actief toelichten."]]],
["Een adviseur heeft met een mkb-klant een doorlopende adviesrelatie. De klant heeft sinds het afsluiten flink geïnvesteerd in machines. Wat volgt uit de zorgplicht van de adviseur?", [["Hij moet periodiek nagaan of de verzekerde bedragen nog passen en de klant wijzen op het risico van onderverzekering.", "Bij een doorlopende relatie hoort nazorg; ontwikkelingen in het bedrijf kunnen de dekking ontoereikend maken."], ["Niets; de klant is zelf verantwoordelijk voor het melden van nieuwe investeringen, de adviseur hoeft daarin niets te doen.", "De klant moet wijzigingen melden, maar bij een doorlopende relatie heeft de adviseur een eigen actieve rol."], ["Hij moet de verzekerde som zonder overleg met de klant verhogen.", "Wijzigen zonder overleg past niet; de adviseur moet de klant informeren en samen een keuze maken."], ["Hij moet de polis opzeggen en een nieuwe offerte aanvragen.", "Opzeggen is niet nodig; een aanpassing van de bestaande verzekering is meestal voldoende."]]],
["Een installateur gaat naast het uitvoeren van installaties ook betaalde ontwerp- en adviesopdrachten doen. De adviseur weet dit. Wat moet hij doen?", [["De klant wijzen op het ontbreken van dekking voor adviesfouten en een BAV bespreken.", "Zuivere vermogensschade door adviesfouten valt doorgaans buiten de AVB; een gewijzigde bedrijfsactiviteit kan zo een gat in de dekking veroorzaken."], ["Niets, omdat de AVB alle activiteiten van het bedrijf automatisch meeverzekert.", "De AVB dekt de omschreven activiteiten en meestal geen zuivere vermogensschade."], ["De AVB direct opzeggen, omdat die niet meer bij het bedrijf past.", "De AVB blijft nodig voor de installatiewerkzaamheden; er moet hooguit iets worden aangevuld."], ["Wachten tot er een claim komt en dan nagaan wat er gedekt is.", "Zorgplicht is vooruitkijken; achteraf vaststellen dat er geen dekking is, is te laat."]]],
["Een klant besluit na advies bewust geen bedrijfsschadeverzekering te sluiten. Waarom is het belangrijk dit in het dossier vast te leggen?", [["Om te kunnen aantonen dat de klant op het risico is gewezen en bewust heeft gekozen.", "Een goed dossier is bij een klacht of aansprakelijkstelling het bewijs dat de adviseur zijn zorgplicht is nagekomen."], ["Omdat de verzekeraar het adviesdossier van de adviseur vooraf moet goedkeuren.", "Het adviesdossier is van de adviseur en hoeft niet door een verzekeraar te worden goedgekeurd."], ["Omdat de klant daarmee afstand doet van alle toekomstige claims tegen de adviseur.", "Vastlegging is bewijs van de advisering, geen afstand van rechten door de klant."], ["Omdat de klant de verzekering dan later niet meer kan afsluiten.", "De klant kan later alsnog verzekeren; vastlegging beperkt die mogelijkheid niet."]]],
["Wat moet een distributeur op grond van de IDD-regels vóór het sluiten van iedere schadeverzekering in elk geval doen, ook bij een zakelijke klant?", [["De verlangens en behoeften van de klant vaststellen en daarop aansluitend aanbieden.", "Deze wensen-en-behoeftentoets geldt voor alle verzekeringsdistributie, met of zonder advies."], ["Een premievergelijking maken tussen ten minste drie verschillende verzekeraars.", "De IDD verplicht niet tot een vergelijking van drie verzekeraars; de kern is aansluiting op wensen en behoeften."], ["De klant laten verklaren dat hij de polisvoorwaarden volledig heeft gelezen.", "Zo'n verklaring vervangt de plicht van de distributeur om wensen en behoeften vast te stellen niet."], ["Niets bijzonders, want de IDD geldt alleen voor levensverzekeringen.", "De IDD geldt voor alle verzekeringsdistributie, dus ook voor schadeverzekeringen."]]],
["Welk gestandaardiseerd document moet bij een schadeverzekering (niet-leven) vóór het sluiten aan de klant worden verstrekt op grond van de IDD?", [["Het informatiedocument over het verzekeringsproduct (IPID).", "Het IPID geeft in een vast format beknopt weer wat wel en niet is verzekerd, zodat producten vergelijkbaar zijn."], ["Het essentiële-informatiedocument (EID) onder PRIIPs.", "Het EID is bedoeld voor verpakte beleggingsproducten, zoals beleggingsverzekeringen, niet voor schadeverzekeringen."], ["Het ESIS-formulier.", "Het ESIS-formulier hoort bij hypothecair krediet."], ["Het Uniform Pensioenoverzicht.", "Het UPO is een pensioenoverzicht en heeft niets met schadeverzekeringen te maken."]]],
["Hoeveel uur bijscholing per jaar schrijft de IDD minimaal voor aan personen die verzekeringen distribueren?", [["15 uur.", "De IDD vraagt ten minste 15 uur per jaar; Nederland vult dit in via het stelsel van permanente educatie, zoals deze PA-module."], ["8 uur.", "Dat is minder dan het Europese minimum van 15 uur."], ["40 uur.", "Zo veel schrijft de IDD niet voor; het minimum is 15 uur."], ["Geen minimum; alleen het initiële diploma telt.", "De IDD verlangt juist dat kennis en vaardigheden op peil blijven via jaarlijkse bijscholing."]]],
["Wat geldt op grond van de IDD voor de beloning van een adviseur die zakelijke schadeverzekeringen bemiddelt?", [["De beloning mag het klantbelang niet schaden en de klant hoort de aard ervan te kennen.", "Provisie is bij schadeverzekeringen toegestaan, maar mag geen prikkel geven die het klantbelang schaadt; transparantie over de aard van de beloning is verplicht."], ["Provisie is bij alle schadeverzekeringen, ook zakelijke, wettelijk verboden.", "Het Nederlandse provisieverbod geldt voor onder meer hypotheken en complexe producten, niet voor gewone schadeverzekeringen."], ["Bij zakelijke klanten hoeft de adviseur niets over zijn beloning te vertellen.", "De informatieplicht over de aard van de beloning geldt bij verzekeringsdistributie ook tegenover zakelijke klanten."], ["Alleen een vaste fee per uur is als beloning toegestaan.", "De IDD schrijft geen beloningsvorm voor; ook provisie kan, mits in lijn met het klantbelang."]]],
["Een assurantiekantoor bemiddelt uitsluitend in schadeverzekeringen. Valt het als bemiddelaar onder de Wwft?", [["Nee; de Wwft wijst wel bemiddelaars in levensverzekeringen aan, maar niet in schade.", "De sanctieregelgeving geldt wel voor iedereen; het kantoor moet dus nog steeds alert zijn op gesanctioneerde personen."], ["Ja, iedere financiële dienstverlener met een AFM-vergunning valt onder de Wwft.", "De Wwft geldt voor aangewezen instellingen; een AFM-vergunning voor schadebemiddeling maakt een kantoor niet automatisch Wwft-plichtig."], ["Ja, maar alleen voor zakelijke klanten en niet voor particulieren.", "Het onderscheid zakelijk of particulier bepaalt niet of de Wwft geldt; dat doet het soort dienstverlening."], ["Alleen als het kantoor meer dan tien medewerkers in dienst heeft.", "De omvang van het kantoor bepaalt niet of het onder de Wwft valt."]]],
["Wie is bij een bv in elk geval aan te merken als uiteindelijk belanghebbende (UBO)?", [["Een natuurlijk persoon met direct of indirect meer dan 25% van de aandelen of stemrechten.", "Dit is het kerncriterium voor UBO's bij vennootschappen; als niemand daaraan voldoet, geldt het hoger leidinggevend personeel als pseudo-UBO."], ["Iedere aandeelhouder, ongeacht de omvang van zijn direct of indirect gehouden aandelenbelang in de bv.", "Een klein aandelenbelang maakt iemand nog geen UBO; de drempel ligt boven de 25%."], ["Uitsluitend de statutair bestuurder, ongeacht wie de aandelen houdt.", "De bestuurder is niet automatisch UBO; die rol is pas aan de orde als er geen UBO op grond van eigendom of zeggenschap is."], ["De accountant die de jaarrekening van de bv controleert en goedkeurt.", "De accountant is een externe dienstverlener en geen belanghebbende in de vennootschap."]]],
["Een Wwft-instelling stelt een ongebruikelijke transactie vast. Waar moet zij die melden en wat mag zij de cliënt daarover vertellen?", [["Bij FIU-Nederland; de cliënt mag niet over de melding worden ingelicht.", "De geheimhoudingsplicht voorkomt dat de cliënt wordt gewaarschuwd en een onderzoek wordt gefrustreerd."], ["Bij de AFM; de cliënt moet direct na de melding worden ingelicht.", "Meldingen gaan naar FIU-Nederland, en de cliënt informeren is juist niet toegestaan."], ["Bij de politie; de cliënt mag worden ingelicht na afloop van het onderzoek.", "Ongebruikelijke transacties worden bij FIU-Nederland gemeld; het informeren van de cliënt is verboden."], ["Bij de Belastingdienst; de cliënt moet schriftelijk toestemming geven.", "Een melding vereist geen toestemming van de cliënt en gaat niet naar de Belastingdienst."]]],
["Voor wie gelden de verboden uit de Europese sanctieverordeningen, zoals het verbod om tegoeden ter beschikking te stellen aan gesanctioneerde personen?", [["Voor iedereen in de EU, ook voor kantoren die niet onder de Wwft vallen.", "Sanctieregels werken rechtstreeks en gelden voor alle personen en ondernemingen in de EU, los van de Wwft."], ["Alleen voor banken en andere instellingen die betalingen verwerken.", "Banken hebben een belangrijke rol, maar de verboden gelden voor iedereen."], ["Alleen voor instellingen die onder de Wwft vallen.", "Sanctieregelgeving en de Wwft zijn verschillende regimes; ook niet-Wwft-instellingen moeten de sancties naleven."], ["Alleen voor ondernemingen die zaken doen buiten de EU.", "Ook binnenlandse transacties met een gesanctioneerde persoon zijn verboden."]]],
["Bij de behandeling van een schadeclaim blijkt dat de UBO van de zakelijke klant op een EU-sanctielijst staat. Wat is juist?", [["Niet uitkeren, de tegoeden bevriezen en de treffer melden volgens de sanctieregels.", "Betalen aan of ten behoeve van een gesanctioneerde persoon is verboden, ook als de claim op zich gedekt is."], ["De uitkering gewoon doen, omdat de claim onder de polisdekking valt.", "Een gedekte claim maakt een betaling niet toegestaan als sanctieregels zich daartegen verzetten."], ["De uitkering doen, mits de betrokken UBO daarvoor schriftelijk toestemming geeft.", "Toestemming van de gesanctioneerde persoon verandert niets aan het verbod."], ["Alleen het eigen risico inhouden en de rest van de schade uitbetalen.", "Een gedeeltelijke betaling is evengoed in strijd met het sanctieverbod."]]],
["Wat regelt een sanctieclausule in een zakelijke polis?", [["De verzekeraar hoeft niet te dekken of uit te keren als dat sanctieregels schendt.", "De clausule voorkomt dat de verzekeraar contractueel tot iets verplicht is wat wettelijk verboden is."], ["De verzekeringnemer betaalt een boete bij te late betaling van de premie.", "Dat gaat over premiebetaling en heeft niets met internationale sancties te maken."], ["De verzekeraar mag zelf sancties opleggen als hij fraude ontdekt.", "Fraudemaatregelen zijn iets anders; de sanctieclausule gaat over internationale sanctieregelgeving."], ["Schade in landen buiten de EU is in alle gevallen uitgesloten van dekking.", "De clausule sluit geen landen uit als zodanig, maar alleen dekking die in strijd is met sanctieregels."]]],
["Wat is in schadeverzekeringen het verschil tussen schade door neerslag en schade door overstroming?", [["Neerslag komt uit de lucht; overstroming ontstaat door falende of overlopende waterkeringen.", "Neerslag is regen, sneeuw, hagel of smeltwater dat het gebouw binnendringt; overstroming komt van het bezwijken of overlopen van dijken, kaden of andere waterkeringen. Neerslag is meestal gedekt, overstroming vaak uitgesloten of beperkt verzekerbaar."], ["Neerslag ontstaat door een dijkdoorbraak of kadeval; overstroming is water door hevige regenval.", "Dit is precies omgekeerd."], ["Er is geen verschil; beide termen worden in polissen zonder onderscheid gebruikt.", "Polissen maken juist een scherp onderscheid, met grote gevolgen voor de dekking."], ["Neerslag is alleen hagel en sneeuw; al het andere water heet overstroming.", "Ook regen en smeltwater vallen onder neerslag."]]],
["Wanneer kan een ondernemer een tegemoetkoming krijgen op grond van de Wet tegemoetkoming schade bij rampen (WTS)?", [["Als de schade door een aangewezen ramp komt en redelijkerwijs niet verzekerbaar was.", "De WTS is een vangnet; schade die redelijkerwijs verzekerbaar was, komt niet voor een tegemoetkoming in aanmerking."], ["Altijd, als aanvulling op de uitkering die de verzekeraar al heeft gedaan.", "De WTS vult geen verzekeringsuitkering aan; zij is bedoeld voor niet verzekerbare schade."], ["Ook als de schade verzekerbaar was, maar de ondernemer geen verzekering had.", "Wie een verzekerbaar risico niet verzekert, kan geen beroep doen op de WTS."], ["Alleen als het gaat om schade aan een particuliere woning, niet aan een bedrijf.", "Ook ondernemers kunnen onder voorwaarden in aanmerking komen."]]],
["Een klant legt een groot zonnepanelendak op zijn bedrijfshal en plaatst een batterijopslag. Wat is voor de adviseur relevant?", [["Het risico verandert; dit melden en verzekerde som en preventie-eisen beoordelen.", "Zonnepanelen en batterijen verhogen de waarde en kunnen het brandrisico beïnvloeden; veel polissen kennen een meldplicht voor risicowijziging."], ["Niets; verduurzaming van een pand heeft geen invloed op het verzekerde risico.", "Nieuwe installaties veranderen zowel de waarde als het brandrisico van het pand."], ["Zonnepanelen en batterijen op bedrijfspanden zijn wettelijk onverzekerbaar.", "Zonnepanelen zijn verzekerbaar, al kunnen verzekeraars voorwaarden stellen."], ["Alleen de AVB moet worden aangepast; de opstalpolis blijft ongewijzigd.", "Juist de opstal- of brandverzekering wordt direct geraakt door de nieuwe installatie."]]],
["Is de Verordening duurzaamheidsinformatie (SFDR) van toepassing op het advies over een brandverzekering voor een bedrijf?", [["Nee; de SFDR ziet op producten met een beleggingscomponent, niet op schadeverzekeringen.", "De SFDR ziet op onder meer verzekeringsgebaseerde beleggingsproducten en pensioenproducten; bij schadeadvies spelen klimaatrisico's wel inhoudelijk een rol."], ["Ja, de SFDR geldt voor iedere verzekering die een adviseur in Nederland bemiddelt.", "De SFDR is beperkt tot onder meer beleggingsproducten, beleggingsverzekeringen en pensioenen."], ["Ja, maar alleen als de klant een beursgenoteerde onderneming is.", "De SFDR knoopt aan bij het soort financieel product, niet bij de beursnotering van de klant."], ["Nee, omdat de SFDR uitsluitend voor banken en vermogensbeheerders geldt.", "De SFDR geldt ook voor onder meer verzekeraars en adviseurs, maar alleen voor bepaalde producten."]]],
["Welke maatregel is een vorm van risicofinanciering en niet van risicobeheersing?", [["Het vormen van een eigen voorziening om toekomstige schaden zelf op te vangen.", "Risicofinanciering gaat over de vraag wie de schade betaalt: zelf (eigen risico, voorziening) of een ander (verzekering)."], ["Het plaatsen van een sprinklerinstallatie in de opslaghal.", "Een sprinkler verkleint de omvang van een brand; dat is beheersing van het risico, niet de financiering ervan."], ["Het geven van een veiligheidstraining aan het magazijnpersoneel.", "Training verkleint de kans op ongevallen en is daarmee een preventieve beheersmaatregel."], ["Het opsplitsen van de opslag over twee gescheiden brandcompartimenten.", "Spreiding beperkt de maximale schade per gebeurtenis; ook dat is risicobeheersing."]]],
["Wat wordt bij risicomanagement verstaan onder het restrisico?", [["Het risico dat overblijft nadat preventieve en beperkende maatregelen zijn genomen.", "Maatregelen nemen een risico zelden helemaal weg; wat resteert moet de ondernemer zelf dragen of verzekeren."], ["Het deel van de schade dat valt onder het eigen risico van de polis.", "Het eigen risico is een financieringskeuze in de polis; het restrisico is een breder begrip uit de risicoanalyse."], ["Een risico dat verzekeraars wettelijk niet mogen verzekeren.", "Dat is een onverzekerbaar risico, zoals een boete; het begrip restrisico gaat daar niet over."], ["De schade die na afwikkeling van een claim nog door een derde moet worden betaald.", "Dat gaat over verhaal en subrogatie na een schade, niet over de risicoanalyse vooraf."]]],
["Een groot internationaal concern richt een eigen verzekeringsmaatschappij op die alleen risico's van de groepsbedrijven verzekert. Hoe heet zo'n maatschappij?", [["Een captive.", "Een captive is een verzekeraar binnen het concern; het concern houdt zo risico in eigen beheer en kan herverzekering inkopen."], ["Een onderlinge waarborgmaatschappij.", "Een onderlinge is van haar leden-verzekerden, vaak uit een branche of regio; zij is geen dochter van één concern."], ["Een gevolmachtigd agent.", "Een gevolmachtigde accepteert namens een verzekeraar, maar draagt zelf geen risico en is geen verzekeraar."], ["Een coassuradeur.", "Een coassuradeur neemt een aandeel in een risico van een andere verzekeringnemer en is niet aan één concern gebonden."]]],
["Een kleine bv draait volledig op de kennis en klantcontacten van de directeur-grootaandeelhouder. Welk risico verdient bij de risico-inventarisatie dan nadrukkelijk aandacht?", [["Uitval van deze sleutelfiguur door ziekte, arbeidsongeschiktheid of overlijden.", "Bij afhankelijkheid van één persoon kan uitval de continuïteit bedreigen; dat risico valt buiten de klassieke zaak- en aansprakelijkheidspolissen."], ["Alleen het risico op brand, omdat dat bij elk bedrijf het grootste risico is.", "Brand is belangrijk, maar bij deze bv ligt een minstens zo groot risico bij de persoon van de directeur."], ["Geen bijzonder risico, omdat een bv als rechtspersoon los staat van de bestuurder.", "Juridisch staat de bv los van de dga, maar economisch kan het bedrijf zonder hem stilvallen."], ["Het risico van koersdalingen van de aandelen in de bv.", "Bij een niet-beursgenoteerde bv speelt koersrisico nauwelijks; de kwetsbaarheid zit in de bedrijfsvoering."]]],
["Waarom is brandcompartimentering in een bedrijfsgebouw van belang voor de verzekeraar?", [["Het beperkt de maximale schade per brand, wat acceptatie, capaciteit en premie beïnvloedt.", "Brandwerende scheidingen houden een brand binnen één compartiment; de verzekeraar kijkt naar die maximale schade bij het bepalen van zijn aandeel en prijs."], ["Het is een wettelijke voorwaarde voordat een brandverzekering mag worden gesloten.", "Bouwregels stellen eisen aan brandveiligheid, maar een verzekering sluiten is daar niet wettelijk van afhankelijk."], ["Het zorgt ervoor dat de evenredigheidsregel niet meer kan worden toegepast.", "Onderverzekering hangt af van verzekerde som en waarde, niet van de bouwkundige indeling van het pand."], ["Het maakt een afzonderlijke bedrijfsschadeverzekering voor het bedrijf in alle gevallen overbodig.", "Ook een brand in één compartiment kan het bedrijf stilleggen; de behoefte aan bedrijfsschadedekking blijft."]]],
["Waarop moet de hoogte van het eigen risico op de zakelijke polissen van een klant vooral worden afgestemd?", [["Op de financiële draagkracht en liquiditeit van de onderneming.", "Een eigen risico bespaart premie, maar het bedrijf moet het bedrag bij een of meer schaden ook echt kunnen betalen."], ["Op het eigen risico dat de concurrenten van de klant hanteren.", "Wat concurrenten kiezen zegt niets over wat deze onderneming financieel kan opvangen."], ["Op het laagste eigen risico dat de verzekeraar aanbiedt, ongeacht de premie.", "Een zo laag mogelijk eigen risico is niet altijd doelmatig; kleine schaden betaalt de klant dan via een hogere premie."], ["Op het bedrag van de grootste schade die het bedrijf ooit heeft gehad.", "Een eerdere schade is een indicatie, maar de vraag is wat het bedrijf nu financieel kan dragen."]]],
["Een adviseur neemt een nieuwe zakelijke klant over die al jaren polissen heeft bij verschillende verzekeraars. Wat is een zinvolle eerste stap?", [["Een polisanalyse maken om dubbele dekkingen en gaten ten opzichte van het risicoprofiel te vinden.", "Polissen die los van elkaar zijn gesloten overlappen vaak of laten risico's onbedekt; dat blijkt pas als je ze naast het risicoprofiel legt."], ["Alle bestaande polissen direct opzeggen en bij één verzekeraar opnieuw afsluiten.", "Opzeggen zonder analyse kan dekkingsgaten veroorzaken, bijvoorbeeld bij claims-made-polissen of lopende schaden."], ["De polissen ongewijzigd laten doorlopen, omdat de vorige adviseur verantwoordelijk blijft voor zijn advies.", "Wie de klant overneemt, heeft een eigen zorgplicht voor het advies vanaf dat moment."], ["Alleen de premies vergelijken en de goedkoopste aanbieder kiezen.", "Premie zegt niets over de passendheid van de dekking; eerst moet duidelijk zijn wat er gedekt moet worden."]]],
["Een chemisch bedrijf besluit een gevaarlijke productielijn te stoppen omdat het risico niet verzekerbaar en niet goed te beheersen is. Welke vorm van risicobehandeling is dit?", [["Risicovermijding.", "Door de activiteit te staken verdwijnt het risico; dat is vermijden, de meest vergaande vorm van risicobehandeling."], ["Risico-overdracht.", "Bij overdracht gaat het risico naar een ander, bijvoorbeeld een verzekeraar of contractpartij; hier verdwijnt het risico juist."], ["Risicoreductie.", "Bij reductie blijft de activiteit bestaan en worden kans of omvang verkleind; hier stopt de activiteit."], ["Risicoacceptatie.", "Accepteren betekent het risico bewust zelf dragen; het bedrijf kiest hier ervoor het risico niet langer te lopen."]]],
["Hoe wordt ontploffing in de gangbare Verbondsdefinitie in de kern omschreven?", [["Een plotselinge, hevige krachtsuiting door uitzetting van gassen of dampen.", "Kern is de plotselinge en hevige uitwerking van gas- of dampspanning; een langzaam scheurend vat valt daar niet onder."], ["Elke scheur in een tank of leiding waardoor een vloeistof ontsnapt.", "Lekkage of scheuren zonder plotselinge, hevige krachtsuiting van gassen of dampen is geen ontploffing."], ["Elke luide knal, ook als er geen schade door drukgolf ontstaat.", "Het gaat om de krachtsuiting zelf en de schade daardoor, niet om het geluid."], ["Uitsluitend een explosie door springstof of vuurwerk.", "De definitie is ruimer: ook een gasexplosie in een installatie valt eronder."]]],
["Bij onweer slaat de bliksem in een hoogspanningsmast verderop. Door overspanning op het net raken computers in een kantoor beschadigd. Wat is juist?", [["Dit is geen blikseminslag in het pand; overspanning is vaak alleen beperkt gedekt.", "Polissen onderscheiden blikseminslag in of op het verzekerde object van inductie en overspanning; voor die laatste gelden vaak eigen regels."], ["Dit is altijd brandschade, omdat bliksem de oorzaak is.", "Zonder vuur met vlammen is er geen brand, ook al is bliksem de bron van de overspanning."], ["Dit is nooit gedekt, omdat de bliksem buiten het verzekerde adres is ingeslagen.", "De schade ontstaat wel aan verzekerde zaken op het adres; of overspanning gedekt is, hangt van de polis af."], ["Dit valt altijd onder de aansprakelijkheidsverzekering van de netbeheerder van het net.", "Een netbeheerder is niet zonder meer aansprakelijk voor bliksem; voor de eigen schade kijkt de klant eerst naar zijn eigen polis."]]],
["Door kortsluiting brandt de elektromotor van een machine door, zonder dat er vlammen ontstaan die zich verder uitbreiden. Welke verzekering ligt het meest voor de hand voor deze schade?", [["Een machinebreukverzekering, omdat dit een interne schade zonder brand is.", "Zonder vuur dat zich zelfstandig uitbreidt is er geen brand; de machinebreukpolis dekt juist plotselinge schade van binnenuit."], ["De brandverzekering, omdat kortsluiting altijd als brand geldt.", "Kortsluiting is een oorzaak, geen gebeurtenis die vanzelf onder het begrip brand valt; vlammen die zich uitbreiden ontbreken hier."], ["De aansprakelijkheidsverzekering voor bedrijven.", "De AVB dekt schade aan derden; schade aan een eigen machine valt daarbuiten."], ["Geen enkele verzekering, omdat kortsluiting altijd onder slijtage valt.", "Kortsluiting is niet per definitie slijtage; een plotselinge onvoorziene storing kan op een machinebreukpolis zijn gedekt."]]],
["Welke oorzaak van schade valt typisch onder een machinebreukverzekering?", [["Een bedieningsfout of een plotselinge materiaal- of constructiefout van binnenuit.", "Machinebreuk dekt plotselinge en onvoorziene schade aan de machine zelf, ook door eigen fouten of interne oorzaken."], ["Geleidelijke slijtage door jarenlang normaal gebruik.", "Slijtage is voorzienbaar en geen onzeker voorval; het valt onder onderhoudskosten, niet onder de verzekering."], ["Letselschade die een op hol geslagen machine toebrengt aan een bezoeker van het bedrijf.", "Letsel van derden valt onder de aansprakelijkheidsverzekering, niet onder een zaakverzekering voor de machine."], ["Het omzetverlies doordat de machine weken stilstaat.", "Dat is bedrijfsschade; daarvoor is een aparte (machine)bedrijfsschadedekking nodig."]]],
["Wat houdt een indexclausule op een opstalverzekering voor een bedrijfspand in?", [["De verzekerde som wordt periodiek aangepast aan een index van bouwkosten.", "Zo groeit de verzekerde som mee met de herbouwkosten en wordt het risico op onderverzekering beperkt."], ["De premie wordt jaarlijks verlaagd zolang er geen schade wordt gemeld.", "Dat is een vorm van no-claimkorting; een indexclausule ziet op de verzekerde som."], ["De uitkering wordt na een schade verminderd met de inflatie sinds de ingangsdatum.", "De clausule werkt juist ten gunste van de verzekerde door de som te laten meegroeien."], ["De verzekeraar mag de voorwaarden jaarlijks eenzijdig aan de markt aanpassen.", "Dat is een wijzigingsclausule voor voorwaarden; indexatie gaat over bedragen."]]],
["Een verzekeraar biedt een garantie tegen onderverzekering aan op een opstalpolis. Wat houdt dat in?", [["De verzekeraar ziet onder voorwaarden af van de evenredigheidsregel, vaak na taxatie.", "De verzekeringnemer krijgt zekerheid dat een te lage som niet tot een naar verhouding lagere uitkering leidt, zolang aan de afspraken is voldaan."], ["De verzekeraar vergoedt elke schade, ook boven de herbouwwaarde.", "De garantie heft de evenredigheidsregel op, maar het indemniteitsbeginsel blijft gelden: niet meer dan de werkelijke schade."], ["De verzekeringnemer hoeft nooit meer wijzigingen aan het pand te melden.", "Verbouwingen of uitbreidingen moeten vaak juist worden gemeld; anders kan de garantie vervallen."], ["De verzekeraar garandeert dat de premie gedurende de hele looptijd van de polis niet stijgt.", "Het gaat om de berekening van de uitkering, niet om een vaste premie."]]],
["Een bedrijfspand is door een deskundige getaxeerd en de verzekeraar heeft dat taxatierapport geaccepteerd. Na een brand stelt de verzekeraar dat het pand minder waard was. Wat is juist?", [["De getaxeerde waarde staat in beginsel vast, behalve bijvoorbeeld bij bedrog.", "Een aanvaarde deskundigentaxatie voorkomt discussie achteraf; zolang de taxatie geldig is, kan de verzekeraar die waarde niet zomaar opnieuw betwisten."], ["De verzekeraar mag de waarde na elke schade opnieuw laten vaststellen en de taxatie negeren.", "Daarmee zou de taxatie haar functie verliezen; die is juist bedoeld om waardediscussie na een schade te voorkomen."], ["De verzekeraar mag de uitkering naar eigen inzicht verlagen, omdat taxaties altijd te hoog zijn.", "Er bestaat geen algemene bevoegdheid om een geaccepteerde taxatie terzijde te schuiven."], ["De taxatie telt alleen als de verzekeringnemer het pand binnen een jaar herbouwt.", "De taxatie gaat over de waarde; eventuele herbouwafspraken staan daar los van."]]],
["Een ondernemer besluit zijn afgebrande bedrijfspand niet te herbouwen. Op welke basis wordt in veel polissen dan uitgekeerd?", [["Op een lagere grondslag, zoals de verkoopwaarde, als die lager is dan de herbouwwaarde.", "De herbouwwaarde vergoedt de kosten van daadwerkelijk herbouwen; wie niet herbouwt, maakt die kosten niet en krijgt vaak een lagere vergoeding."], ["Altijd op de herbouwwaarde, omdat die als verzekerde som op het polisblad van de opstalpolis staat.", "Veel voorwaarden koppelen de herbouwwaarde aan herbouw of herstel; zonder herbouw geldt vaak een lagere grondslag."], ["Op de WOZ-waarde, omdat die door de gemeente is vastgesteld.", "De WOZ-waarde is een fiscale waarde inclusief grond en geen gebruikelijke uitkeringsgrondslag van een opstalpolis."], ["Er wordt niets uitgekeerd, omdat herbouw een voorwaarde voor dekking is.", "Niet herbouwen leidt doorgaans tot een andere berekeningsgrondslag, niet tot het vervallen van de dekking."]]],
["Wat wordt op een zakelijke brandpolis verstaan onder opruimingskosten?", [["De kosten van afbreken, wegruimen en afvoeren van restanten na een gedekte schade.", "Na een brand moet het puin weg voordat kan worden herbouwd; deze kosten worden vaak bovenop de verzekerde som tot een maximum vergoed."], ["De kosten om het pand vóór de schade schoon en ontruimd te houden als preventie.", "Preventief onderhoud en ordelijk houden zijn kosten van het bedrijf zelf; opruimingskosten volgen op een schade."], ["De kosten om goederen tijdens een beginnende brand in veiligheid te brengen.", "Dat zijn bereddingskosten: kosten om dreigende schade te voorkomen of te beperken."], ["De kosten van bodemsanering die altijd volledig worden vergoed.", "Sanering van verontreinigde grond is vaak uitgesloten of slechts beperkt meeverzekerd."]]],
["Een belegger verhuurt een bedrijfspand. Na een brand kan de huurder het pand maanden niet gebruiken en betaalt geen huur meer. Welke dekking beschermt de verhuurder tegen dit inkomensverlies?", [["Een dekking voor huurderving.", "Huurderving vergoedt de gederfde huur gedurende de herstelperiode na een gedekte schade, vaak met een maximumtermijn."], ["De bedrijfsschadeverzekering van de huurder.", "Die dekt het verlies aan brutowinst van de huurder zelf, niet het huurverlies van de verhuurder."], ["De aansprakelijkheidsverzekering van de verhuurder.", "De AVB dekt aansprakelijkheid tegenover derden, geen eigen inkomensverlies."], ["Een rechtsbijstandverzekering voor het innen van de huur.", "Als de huurovereenkomst geen huur verplicht tijdens onbruikbaarheid, valt er niets te innen; het is een te verzekeren verlies."]]],
["Een bedrijfsschadepolis kent een wachttijd van een aantal dagen. Wat betekent dat?", [["Het verlies over de eerste dagen na de schade wordt niet vergoed: een eigen risico in tijd.", "Korte onderbrekingen draagt de ondernemer zelf; de vergoeding begint na afloop van de wachttijd."], ["De verzekeraar heeft dat aantal dagen de tijd om de schade te beoordelen en een expert te sturen.", "Een behandeltermijn is iets anders; de wachttijd gaat over het tijdvak waarover niet wordt uitgekeerd."], ["De verzekering gaat pas zoveel dagen na het sluiten in.", "Dat is een karenztijd bij ingang; de wachttijd bij bedrijfsschade telt vanaf het moment van de schade."], ["De verzekeringnemer moet de schade binnen dat aantal dagen melden.", "De meldingstermijn staat los van de wachttijd en bepaalt niet over welk tijdvak wordt vergoed."]]],
["Door een stroomstoring bij de netbeheerder ligt de productie van een fabriek twee dagen stil, zonder dat er bij de fabriek zelf materiële schade is. Is dit verlies op een traditionele bedrijfsschadepolis gedekt?", [["In de regel niet, tenzij uitval van openbare nutsvoorzieningen is meeverzekerd.", "Traditionele bedrijfsschade vereist materiële schade door een gedekte gebeurtenis bij de verzekerde; externe uitval vraagt een aparte uitbreiding."], ["Ja, want elke onderbreking van de productie valt onder de bedrijfsschadeverzekering.", "Bedrijfsschade is geen dekking voor elke stilstand; er moet een gedekte materiële schade aan ten grondslag liggen."], ["Ja, mits de netbeheerder aansprakelijk is.", "Of de netbeheerder aansprakelijk is, bepaalt de verhaalsmogelijkheid, niet de dekking op de eigen polis."], ["Nee, want een stroomstoring is altijd een molestrisico.", "Een stroomstoring is geen vorm van molest; de reden dat dekking ontbreekt is het ontbreken van eigen materiële schade."]]],
["Een garagebedrijf heeft auto's van klanten in de werkplaats staan. Na een brand blijken deze auto's niet op de inventarispolis van de garage te staan. Wat had de adviseur moeten signaleren?", [["Dat zaken van derden onder zijn berusting apart moeten worden meeverzekerd.", "Een inventarispolis dekt in beginsel eigen zaken; voor zaken van klanten is een uitbreiding of aparte dekking nodig."], ["Dat auto's van klanten altijd op de AVB zijn gedekt, ook bij brand.", "Voor zaken onder opzicht geldt op de AVB vaak juist een uitsluiting of beperking."], ["Dat de autoverzekering van de klant altijd de schade betaalt, zonder verhaal.", "De cascoverzekeraar van de klant kan wel uitkeren, maar zal daarna proberen te verhalen op de garage."], ["Dat zaken van derden nooit verzekerbaar zijn voor een bedrijf.", "Dat is onjuist; veel inventaris- en goederenpolissen bieden dekking voor zaken van derden."]]],
["Vanaf welke windsnelheid is volgens de gangbare Verbondsdefinitie sprake van storm?", [["Ten minste 14 meter per seconde.", "Die grens komt overeen met windkracht 7; onder die snelheid geldt windschade niet als stormschade."], ["Ten minste 7 meter per seconde.", "Windkracht 7 is iets anders dan 7 meter per seconde; de definitie legt de grens bij 14 meter per seconde."], ["Ten minste 20 meter per seconde.", "Dat ligt rond windkracht 8 à 9; de stormdefinitie begint al lager."], ["Pas als het KNMI officieel code rood heeft afgegeven.", "Een weerwaarschuwing is geen onderdeel van de definitie; het gaat om de gemeten windsnelheid."]]],
["Na een inbraak in een bedrijfspand stelt de verzekeraar dat hij alleen uitkeert bij zichtbare braaksporen. Waarom stellen inbraakdekkingen dit vereiste?", [["Braaksporen tonen aan dat er echt is ingebroken, en niet dat zaken zijn zoekgeraakt.", "Zonder braaksporen is lastig te onderscheiden of zaken zijn weggenomen door inbraak of op een andere manier zijn verdwenen."], ["Omdat de politie zonder braaksporen geen aangifte van inbraak in een bedrijfspand opneemt.", "Aangifte kan ook zonder braaksporen; het vereiste komt uit de polis, niet uit de regels voor aangifte."], ["Omdat schade door diefstal zonder braak altijd onder de AVB valt.", "De AVB dekt aansprakelijkheid tegenover derden, niet het verlies van eigen zaken."], ["Omdat de wet bepaalt dat diefstal zonder braak niet door een verzekeraar mag worden gedekt.", "Er bestaat geen wettelijk verbod; het is een polisvoorwaarde die verzekeraars hanteren."]]],
["Waarom is een elektronicaverzekering voor een kantoor met veel IT-apparatuur een zinvolle aanvulling op de inventarisverzekering?", [["Zij dekt ook plotselinge schade van binnenuit en door eigen handelen, zoals val- en stootschade.", "Een inventarispolis dekt vooral genoemde gebeurtenissen als brand en inbraak; een elektronicapolis dekt ruimer, bijvoorbeeld val- en stootschade."], ["Omdat een inventarispolis nooit elektronische apparatuur dekt.", "Apparatuur valt wel onder inventaris, maar alleen voor de genoemde gebeurtenissen; het verschil zit in de breedte van de dekking."], ["Omdat de elektronicapolis ook de aansprakelijkheid voor datalekken en hacks tegenover klanten dekt.", "Aansprakelijkheid bij een datalek hoort bij een cyber- of aansprakelijkheidsdekking, niet bij een zaakverzekering voor apparatuur."], ["Omdat de wet bedrijven verplicht hun IT-apparatuur apart te verzekeren.", "Er is geen wettelijke verplichting; het is een keuze op basis van het risicoprofiel."]]],
["Een kapotte koffiemachine van een fabrikant veroorzaakt brand in een woonkamer. Welke zaakschade valt onder de productaansprakelijkheidsregeling uit het BW?", [["Schade aan andere zaken voor privégebruik, zoals de inrichting, boven een franchise.", "De regeling beschermt vooral consumenten: schade aan privézaken is gedekt, schade aan het gebrekkige product zelf niet."], ["Ook de schade aan de koffiemachine zelf, omdat juist die machine gebrekkig was en de brand veroorzaakte.", "Schade aan het product zelf valt niet onder de productaansprakelijkheid; daarvoor kan de koper zijn verkoper aanspreken."], ["Alleen schade aan zaken die zakelijk worden gebruikt.", "Het omgekeerde is waar: zaakschade is gedekt als de zaak gewoonlijk voor privégebruik bestemd is en zo werd gebruikt."], ["Alleen personenschade; zaakschade valt nooit onder de regeling.", "De regeling dekt naast personenschade ook zaakschade aan privézaken, zij het met een franchise."]]],
["Een Nederlandse groothandel importeert gereedschap van een fabrikant buiten de Europese Unie en verkoopt het hier. Een gebrekkige zaag veroorzaakt letsel. Wat is juist?", [["De importeur in de EU kan als producent worden aangesproken.", "Wie een product in de EU invoert om het te verhandelen, wordt voor de productaansprakelijkheid met de producent gelijkgesteld; zo hoeft de benadeelde niet buiten de EU te procederen."], ["Alleen de fabrikant buiten de EU kan worden aangesproken.", "Juist om de benadeelde te beschermen geldt de importeur in de EU ook als producent."], ["De groothandel is alleen aansprakelijk als hij schuld heeft aan het gebrek.", "De productaansprakelijkheid is een risicoaansprakelijkheid; schuld hoeft niet te worden bewezen."], ["Niemand is aansprakelijk, omdat het product buiten de EU is gemaakt.", "De plaats van productie sluit aansprakelijkheid niet uit; de importeur vangt dit op."]]],
["Een producent verweert zich met het argument dat het gebrek met de stand van wetenschap en techniek op het moment van in het verkeer brengen niet te ontdekken was. Hoe heet dit verweer?", [["Het ontwikkelingsrisicoverweer.", "Dit is een van de wettelijke verweren van de producent: hij is niet aansprakelijk als het gebrek met de kennis van toen niet was te ontdekken."], ["Het eigen-schuldverweer.", "Eigen schuld ziet op een fout van de benadeelde, die de schadevergoeding kan verminderen; dat is iets anders."], ["Het overmachtsverweer bij wanprestatie.", "Overmacht hoort bij contractuele aansprakelijkheid; productaansprakelijkheid kent een eigen stelsel van verweren."], ["Het verjaringsverweer.", "Verjaring gaat over het verstrijken van tijd na de schade, niet over de kenbaarheid van het gebrek."]]],
["Waarom zijn beroepsziekten met een lange latentietijd, zoals ziekten door asbest, lastig voor de dekking onder een AVB?", [["De ziekte openbaart zich vaak pas na vele jaren, wat vragen oproept over welke polis dekt.", "Bij lange latentie kunnen de blootstelling, het ontstaan van de ziekte en de claim in verschillende polisperioden of bij verschillende verzekeraars vallen."], ["Beroepsziekten vallen wettelijk nooit onder de werkgeversaansprakelijkheid.", "Een werkgever kan wel aansprakelijk zijn voor beroepsziekten als hij zijn zorgplicht heeft geschonden."], ["Beroepsziekten worden altijd volledig door de WIA gecompenseerd, zodat er geen schade overblijft.", "De WIA vergoedt slechts een deel van het inkomensverlies en geen smartengeld; er blijft schade over."], ["Beroepsziekten zijn per definitie opzettelijk veroorzaakt en daarom uitgesloten.", "Een werkgever veroorzaakt een beroepsziekte zelden opzettelijk; de opzetuitsluiting is hier meestal niet aan de orde."]]],
["Een winkelketen laat de etalages verbouwen door een zelfstandig aannemersbedrijf. Een medewerker van de aannemer laat een stelling vallen op een klant. Kan de winkelketen op grond van het BW aansprakelijk zijn?", [["Ja, wie in zijn bedrijf werk laat doen door een niet-ondergeschikte, kan voor diens fouten aansprakelijk zijn.", "Het BW kent een aansprakelijkheid van de opdrachtgever voor fouten van niet-ondergeschikten bij werkzaamheden ter uitoefening van zijn bedrijf."], ["Nee, alleen een werkgever kan voor fouten van anderen aansprakelijk zijn, en de aannemer werkt als zelfstandige.", "Naast de aansprakelijkheid voor ondergeschikten kent het BW ook aansprakelijkheid voor niet-ondergeschikten."], ["Nee, omdat de aannemer een eigen AVB heeft.", "Het bestaan van een verzekering bij de aannemer bepaalt niet of de winkelketen aansprakelijk is."], ["Ja, maar alleen als de winkelketen de stelling zelf heeft geleverd.", "De aansprakelijkheid hangt niet af van wie het materiaal leverde, maar van de werkzaamheden ter uitoefening van het bedrijf."]]],
["Een ondernemer huurt een winkelpand en gebruikt het voor zijn bedrijf. Door een gebrek valt een stuk van de gevel op een voorbijganger. Op wie rust volgens het BW in beginsel de risicoaansprakelijkheid voor de gebrekkige opstal?", [["Op degene die het pand in de uitoefening van zijn bedrijf gebruikt.", "Het BW legt de aansprakelijkheid voor een gebrekkige opstal die in een bedrijf wordt gebruikt bij de bedrijfsmatige gebruiker; daarom hoort ook de huurder dit op zijn AVB gedekt te hebben."], ["Altijd op de eigenaar van het pand, ook als een ander er een bedrijf in uitoefent.", "Bij bedrijfsmatig gebruik verschuift de aansprakelijkheid in beginsel naar degene die het bedrijf uitoefent."], ["Op de gemeente, omdat de voorbijganger op de openbare weg liep.", "De gemeente is aansprakelijk voor gebreken aan de weg, niet voor een gebrek aan een particulier pand."], ["Op niemand, omdat het om een onvoorzienbare gebeurtenis gaat.", "Voor gebrekkige opstallen geldt een risicoaansprakelijkheid; voorzienbaarheid van het gebrek is niet beslissend."]]],
["Hoe is milieuschade door geleidelijke verontreiniging op een standaard AVB doorgaans geregeld?", [["Grotendeels uitgesloten; vaak is alleen een plotseling en onzeker voorval gedekt.", "De milieuclausule op de AVB beperkt de dekking tot acute incidenten; voor geleidelijke vervuiling en eigen terrein bestaat een milieuschadeverzekering."], ["Volledig gedekt, omdat milieuschade bij omwonenden of op naburige percelen altijd schade aan derden is.", "Geleidelijke verontreiniging valt doorgaans buiten de AVB; een algemene dekking zou het risico onbeheersbaar maken."], ["Gedekt, maar alleen als de overheid een saneringsbevel geeft.", "Een overheidsbevel maakt een uitgesloten risico niet gedekt; de dekking hangt af van de aard van de gebeurtenis."], ["Gedekt via de opstalverzekering van het bedrijfsterrein.", "Een opstalpolis dekt schade aan het gebouw door genoemde gebeurtenissen, niet de verontreiniging van bodem of water."]]],
["Waarom sluiten veel werkgevers naast hun AVB een collectieve ongevallenverzekering voor hun werknemers?", [["Die keert een vast bedrag uit, los van de vraag of de werkgever aansprakelijk is.", "Een ongevallenverzekering voorkomt dat de werknemer eerst aansprakelijkheid moet bewijzen; dat kan de arbeidsrelatie ontzien."], ["De AVB dekt geen enkele schade van werknemers.", "Een AVB dekt doorgaans wel de werkgeversaansprakelijkheid; de ongevallenverzekering vult aan waar die aansprakelijkheid ontbreekt."], ["Een collectieve ongevallenverzekering is voor iedere werkgever met personeel wettelijk verplicht.", "Er bestaat geen algemene wettelijke plicht; soms vloeit een plicht voort uit een cao."], ["Een ongevallenverzekering vervangt de loondoorbetaling bij ziekte.", "Loondoorbetaling blijft een wettelijke plicht; een ongevallenuitkering is een vast bedrag bij overlijden of blijvende invaliditeit."]]],
["Een accountant beëindigt zijn praktijk. Hij had een beroepsaansprakelijkheidsverzekering op claims-made-basis. Waarom is een uitloopdekking (nadekking) dan belangrijk?", [["Claims over fouten uit de actieve periode kunnen nog worden ingediend na het einde van de polis.", "Bij claims-made moet de aanspraak tijdens de looptijd worden ingesteld; zonder uitloopdekking zijn latere claims onverzekerd."], ["Een uitloopdekking is nodig om tijdens de looptijd van de polis nog nieuwe opdrachten te mogen aannemen.", "Tijdens de looptijd dekt de gewone polis; uitloop ziet op de periode na beëindiging."], ["Een uitloopdekking vergoedt de premie terug als er geen claims zijn geweest.", "Er is geen sprake van premierestitutie; uitloop verlengt de periode waarin claims kunnen worden gemeld."], ["Een uitloopdekking is niet nodig, omdat claims verjaren zodra de praktijk stopt.", "Stoppen met de praktijk laat de verjaringstermijnen van vorderingen niet eerder aflopen."]]],
["Welke verplichting geldt op grond van de IDD en de Wft voor een bemiddelaar in verzekeringen met betrekking tot zijn eigen beroepsaansprakelijkheid?", [["Hij moet een beroepsaansprakelijkheidsverzekering of vergelijkbare garantie hebben.", "De eis beschermt klanten tegen schade door beroepsfouten van de bemiddelaar; de minimumbedragen worden periodiek geïndexeerd."], ["Hij moet uitsluitend een AVB hebben, omdat adviesfouten daaronder vallen.", "Een AVB dekt zuivere vermogensschade door adviesfouten meestal niet; daarvoor is een beroepsaansprakelijkheidsverzekering nodig."], ["Hij hoeft niets te regelen, omdat de verzekeraar voor zijn adviesfouten instaat.", "Een zelfstandige bemiddelaar is zelf verantwoordelijk voor zijn advies; de verzekeraar staat daar niet automatisch voor in."], ["Hij moet alleen een verzekering hebben als hij ook in levensverzekeringen bemiddelt.", "De eis geldt voor verzekeringsbemiddelaars in het algemeen, dus ook voor wie alleen in schade bemiddelt."]]],
["Wat is het doel van de opzichtclausule-uitbreiding die sommige AVB-polissen voor bijvoorbeeld installateurs aanbieden?", [["Schade aan zaken van derden waaraan wordt gewerkt toch tot een maximum meeverzekeren.", "Zaken onder opzicht zijn standaard vaak uitgesloten; een uitbreiding biedt beperkte dekking voor dit typische risico van werken bij klanten."], ["De eigen gereedschappen en meetapparatuur van de installateur meeverzekeren tegen diefstal.", "Eigen gereedschap is een zaakrisico dat op een aparte goederen- of gereedschapspolis hoort."], ["Het herstel van eigen slecht uitgevoerd werk vergoeden.", "De kosten om eigen ondeugdelijk werk over te doen zijn een ondernemersrisico en blijven uitgesloten."], ["De aansprakelijkheid voor adviesfouten bij ontwerpopdrachten dekken.", "Adviesfouten met zuivere vermogensschade horen op een beroepsaansprakelijkheidsverzekering."]]],
["Een groot concern koopt zijn aansprakelijkheidsdekking in lagen: een primaire polis tot een bepaald bedrag en daarboven een of meer excedentpolissen. Wanneer keert een excedentverzekeraar uit?", [["Pas als de schade het bedrag van de onderliggende laag of lagen overschrijdt.", "Een excedent sluit aan op de onderliggende dekking en betaalt alleen het deel daarboven, tot zijn eigen limiet."], ["Bij elke schade, naar verhouding van zijn aandeel in de totale dekking.", "Dat is kenmerkend voor coassurantie; bij lagen betaalt een hogere laag pas als de lagere is uitgeput."], ["Alleen als de primaire verzekeraar failliet is.", "Een excedent is geen vervanging van een failliete verzekeraar maar een aanvulling boven een bepaald bedrag."], ["Alleen als de schade het gevolg is van opzet van het concern.", "Opzet is doorgaans juist uitgesloten; de laag waar een schade valt, hangt van de omvang af."]]],
["Een monteur van een werkgever veroorzaakt door onoplettendheid een ongeval met de bedrijfsbus. De cascoschade komt voor het eigen risico van de werkgever. Kan de werkgever dat eigen risico op grond van het BW op de monteur verhalen?", [["In beginsel niet; dat kan alleen bij opzet of bewuste roekeloosheid van de werknemer.", "Het BW beschermt werknemers tegen aansprakelijkheid voor gewone fouten in het werk; die schade hoort bij het bedrijfsrisico van de werkgever."], ["Ja, volledig, omdat de monteur de schade heeft veroorzaakt.", "Veroorzaken is onvoldoende; voor gewone onachtzaamheid is de werknemer tegenover zijn werkgever niet aansprakelijk."], ["Ja, mits dit in de arbeidsovereenkomst is opgenomen; dan kan het ook bij lichte schuld van de monteur.", "Van deze beschermende regel kan niet zomaar ten nadele van de werknemer worden afgeweken."], ["Ja, maar alleen tot het bedrag van één maandsalaris.", "Een vaste maandsalarisgrens bestaat niet; bij gewone fouten draagt de werkgever de schade."]]],
["Een fabrikant levert onderdelen aan een autobouwer. Door een productiefout moet de autobouwer de onderdelen uit duizenden auto's verwijderen en vervangen. Welke kosten zijn op een AVB doorgaans niet gedekt?", [["De kosten om het eigen gebrekkige onderdeel uit de auto's te halen en te vervangen.", "De AVB dekt schade aan personen en andere zaken, niet de kosten om het eigen geleverde product te vervangen; daarvoor bestaan aparte dekkingen."], ["Personenschade die automobilisten lijden door een ongeval met het onderdeel.", "Letsel van derden door een gebrekkig product is juist de kern van de productaansprakelijkheidsdekking op de AVB."], ["Zaakschade aan andere auto's die door een ongeval met het onderdeel ontstaat.", "Schade aan andere zaken van derden valt in beginsel wel onder de AVB."], ["De kosten van verweer als de autobouwer de fabrikant ten onrechte aansprakelijk stelt.", "De AVB dekt doorgaans ook verweer tegen aanspraken, ook als die ongegrond blijken."]]],
["Een bestuurder van een bv sluit namens de bv een grote inkooporder, terwijl hij weet dat de bv de rekening niet kan betalen en geen verhaal biedt. De leverancier blijft onbetaald. Wat is juist?", [["De bestuurder kan persoonlijk aansprakelijk zijn uit onrechtmatige daad.", "Volgens vaste rechtspraak handelt een bestuurder onrechtmatig als hij namens de vennootschap verplichtingen aangaat waarvan hij weet of behoort te weten dat die niet worden nagekomen."], ["Alleen de bv is aansprakelijk, omdat een bestuurder nooit persoonlijk aansprakelijk is.", "Het uitgangspunt is dat de vennootschap aansprakelijk is, maar bij een persoonlijk ernstig verwijt kan ook de bestuurder worden aangesproken."], ["De bestuurder is alleen aansprakelijk als de bv binnen een jaar failliet gaat.", "Een faillissement is geen voorwaarde voor aansprakelijkheid van de bestuurder tegenover een schuldeiser."], ["De leverancier moet eerst de aandeelhouders aanspreken.", "Aandeelhouders van een bv zijn in beginsel niet aansprakelijk voor schulden van de vennootschap."]]],
["Het bestuur van een bv bestaat uit drie personen. Eén bestuurder was het oneens met een besluit dat tot onbehoorlijk bestuur leidde en heeft geprobeerd de gevolgen te voorkomen. Wat is juist bij aansprakelijkheid tegenover de bv?", [["Hij kan zich disculperen als hem geen ernstig verwijt treft en hij niet nalatig was.", "Bestuurders zijn collectief verantwoordelijk, maar een bestuurder die geen ernstig verwijt treft en niet nalatig was in het afwenden van de gevolgen, kan zich bevrijden."], ["Hij is altijd hoofdelijk voor het geheel aansprakelijk, ongeacht zijn eigen opstelling in het bestuur.", "De collectieve verantwoordelijkheid kent een disculpatiemogelijkheid voor de bestuurder die geen ernstig verwijt treft."], ["Alleen de voorzitter van het bestuur kan aansprakelijk zijn.", "Alle bestuurders dragen verantwoordelijkheid voor het bestuur, niet alleen de voorzitter."], ["Hij is vrij van aansprakelijkheid zolang hij niet zelf heeft getekend.", "Het ondertekenen is niet beslissend; het gaat om de verwijtbaarheid van zijn rol in het bestuur."]]],
["Een bv kan de verschuldigde loonheffingen niet betalen. Wat moet het bestuur doen om de kans op persoonlijke bestuurdersaansprakelijkheid tegenover de Belastingdienst te beperken?", [["Tijdig betalingsonmacht melden bij de Belastingdienst.", "Een tijdige melding voorkomt dat het niet-betalen zonder meer aan de bestuurder wordt toegerekend; zonder melding wordt aansprakelijkheid sterker vermoed."], ["De aangifte loonheffingen uitstellen tot er weer geld is.", "Niet of te laat aangeven verergert de situatie en ontslaat het bestuur niet van zijn verplichtingen."], ["Een D&O-verzekering afsluiten nadat de schuld is ontstaan.", "Een verzekering na het ontstaan van het probleem dekt bekende omstandigheden niet; het lost de meldplicht ook niet op."], ["De schuld laten overnemen door de aandeelhouder.", "Dat kan een oplossing voor betaling zijn, maar vervangt de wettelijke melding van betalingsonmacht niet."]]],
["Een D&O-polis kent een 'side B'-dekking. Wat dekt dit onderdeel?", [["Vergoeding aan de vennootschap van wat zij op grond van een vrijwaring aan de bestuurder betaalde.", "Als de vennootschap haar bestuurder vrijwaart en betaalt, vergoedt side B die uitgave aan de vennootschap."], ["De directe dekking van de bestuurder zelf, voor het geval de vennootschap hem niet wil of kan vrijwaren.", "Dat is side A: de bestuurder wordt rechtstreeks gedekt als de vennootschap niet betaalt of niet kan betalen."], ["De eigen aansprakelijkheid van de vennootschap als rechtspersoon.", "Dat is entity-dekking (side C), die vaak beperkt is tot bepaalde claims."], ["De schade van aandeelhouders door koersdaling van de aandelen.", "Aandeelhoudersclaims kunnen tot een aanspraak leiden, maar side B ziet op terugbetaling aan de vennootschap."]]],
["Een bv wordt overgenomen en de bestuurders treden af. Waarom wordt bij de overname vaak een run-offdekking op de D&O-polis geregeld?", [["Claims over besluiten van vóór de overname kunnen later nog komen, terwijl de oude polis eindigt.", "Een D&O-polis werkt doorgaans op claims-made-basis; zonder run-off zijn latere aanspraken over het oude bestuur niet gedekt."], ["Run-off zorgt ervoor dat de nieuwe eigenaar voor het nieuwe bestuur geen eigen D&O-polis meer hoeft te sluiten.", "Run-off ziet op het verleden; voor het nieuwe bestuur is een eigen dekking nodig."], ["Run-off is verplicht om de overname bij de Kamer van Koophandel te kunnen inschrijven.", "Inschrijving bij de Kamer van Koophandel is niet afhankelijk van een verzekering."], ["Run-off vergoedt de overnamesom als de koper zich bedrogen voelt.", "Een geschil over de overnamesom is geen bestuurdersaansprakelijkheid en wordt elders geregeld."]]],
["Waarom kan een D&O-verzekering ook relevant zijn voor bestuurders van een stichting of vereniging?", [["Ook zij kunnen bij onbehoorlijk bestuur persoonlijk aansprakelijk worden gesteld.", "Sinds die wet gelden voor bestuurders en toezichthouders van verenigingen en stichtingen vergelijkbare aansprakelijkheidsregels als bij bv's en nv's."], ["Bestuurders van stichtingen zijn wettelijk verplicht een D&O-verzekering te hebben.", "Er bestaat geen algemene wettelijke verplichting; het is een keuze, soms wel geëist door subsidiegevers."], ["Een stichting heeft geen eigen vermogen, zodat de bestuurders altijd voor alle schulden instaan.", "Een stichting is een rechtspersoon die zelf voor haar schulden instaat; bestuurders zijn alleen bij een persoonlijk verwijt aansprakelijk."], ["De D&O-verzekering dekt de exploitatietekorten van de stichting.", "Tekorten in de exploitatie zijn een ondernemersrisico en geen schade door een aanspraak op een bestuurder."]]],
["Een aannemer moet na oplevering gedurende een onderhoudstermijn gebreken herstellen. Welke schade dekt een CAR-polis in die termijn doorgaans?", [["Schade die de aannemer bij onderhoudswerk veroorzaakt en schade met een oorzaak uit de bouwperiode.", "Na oplevering loopt de CAR-dekking in beperkte vorm door; zij dekt dan niet meer alle schade aan het werk, maar wel deze specifieke situaties."], ["Alle schade aan het opgeleverde werk, ook door storm of brand tijdens het gebruik door de opdrachtgever.", "Na oplevering is het gebruik voor risico van de opdrachtgever; brand en storm horen dan op zijn opstalpolis."], ["Alleen de kosten van regulier onderhoud zoals schilderwerk.", "Normaal onderhoud is geen onzeker voorval en dus niet verzekerd."], ["Geen enkele schade, omdat de CAR-dekking eindigt bij oplevering.", "Veel CAR-polissen kennen een uitlopende dekking voor de onderhoudstermijn."]]],
["Bij de renovatie van een bestaand kantoorpand raakt het bestaande, niet te renoveren deel beschadigd door de werkzaamheden. Welke CAR-rubriek is hiervoor bedoeld?", [["De rubriek voor bestaande eigendommen van de opdrachtgever.", "Bij renovatie en uitbreiding is het bestaande pand geen 'werk in uitvoering'; daarvoor bestaat een aparte rubriek of uitbreiding."], ["De rubriek voor het werk in uitvoering.", "Die rubriek dekt het nieuw te bouwen of te renoveren werk, niet de bestaande delen daarbuiten."], ["De rubriek voor bouwmaterieel en gereedschap.", "Materieel betreft de machines en het gereedschap van de aannemer, niet het gebouw van de opdrachtgever."], ["De rubriek voor de kosten van extra bewaking van de bouwplaats.", "Bewaking is een preventiemaatregel, geen dekking voor schade aan bestaande eigendommen."]]],
["Een aannemer voert jaarlijks tientallen vergelijkbare projecten uit van beperkte omvang. Welke CAR-vorm sluit daar het best op aan?", [["Een doorlopende CAR-polis die projecten binnen vastgelegde grenzen automatisch dekt.", "Zo hoeft niet voor elk project een aparte polis te worden gesloten en is elk project vanaf de start gedekt."], ["Een aparte projectpolis voor elk project, gesloten na de start van de bouw.", "Een losse polis per project is bewerkelijk; bovendien ontstaat een gat als die pas na de start wordt gesloten."], ["Geen CAR, omdat kleine projecten onder de AVB vallen.", "De AVB dekt aansprakelijkheid, geen schade aan het eigen werk in uitvoering."], ["Een beroepsaansprakelijkheidsverzekering voor alle projecten.", "Die dekt zuivere vermogensschade door ontwerp- of adviesfouten, geen fysieke schade aan het werk."]]],
["Waarom is zwaar bouwmaterieel, zoals een kraan of graafmachine, vaak niet op de CAR-polis maar op een aparte materieelverzekering verzekerd?", [["Het materieel gaat van project naar project, terwijl een project-CAR aan één werk vastzit.", "Een materieelpolis dekt de machines doorlopend, waar ze zich ook bevinden; dat sluit beter aan bij het gebruik ervan."], ["Materieel kan op geen enkele manier worden verzekerd.", "Materieel is wel verzekerbaar, bijvoorbeeld via een materieelverzekering op casco-achtige basis."], ["De CAR-polis dekt uitsluitend materieel dat eigendom is van de opdrachtgever van het werk.", "Ook materieel van de opdrachtgever valt niet vanzelf onder de CAR; de verdeling volgt uit de aard van het object."], ["Een kraan moet altijd op de WAM-polis worden verzekerd.", "Alleen als het materieel als motorrijtuig aan het verkeer deelneemt speelt de WAM; dat zegt niets over de schade aan de machine zelf."]]],
["Een woningcorporatie besluit zelf de CAR-verzekering voor een groot nieuwbouwproject te sluiten in plaats van de aannemer. Wat is daarvan een belangrijk voordeel?", [["De corporatie houdt zelf regie over dekking, verzekerde bedragen en voorwaarden.", "Als opdrachtgever kan zij zeker stellen dat het hele project goed is gedekt en dat er geen gaten of dubbelingen tussen polissen van partijen ontstaan."], ["De aannemer hoeft dan geen enkele aansprakelijkheid meer te dragen voor zijn werk.", "Een CAR-polis neemt de contractuele verplichtingen van de aannemer niet weg."], ["De corporatie kan zo de bouwkosten fiscaal aftrekken.", "Wie de CAR sluit heeft geen invloed op de fiscale behandeling van de bouwkosten."], ["De corporatie hoeft dan geen opstalverzekering meer te sluiten na oplevering.", "Na oplevering eindigt de CAR-dekking grotendeels; de opstal moet dan apart worden verzekerd."]]],
["Bij graafwerkzaamheden raakt een aannemer een ondergrondse kabel. De CAR-polis bepaalt dat bij schade aan kabels een verhoogd eigen risico geldt als niet vooraf een graafmelding (KLIC) is gedaan. Wat is het doel van zo'n clausule?", [["Stimuleren dat de aannemer vooraf de ligging van kabels en leidingen opvraagt.", "Kabelschade is een veelvoorkomend risico; de wettelijke graafmelding en de polisvoorwaarde moeten die schade voorkomen."], ["De kosten van de verplichte graafmelding alsnog laten vergoeden door de CAR-verzekeraar.", "De clausule gaat over het eigen risico bij schade, niet over de kosten van de melding."], ["Kabelschade volledig uitsluiten van de CAR-dekking.", "Met een verhoogd eigen risico blijft de schade gedekt; alleen het deel voor eigen rekening is groter."], ["Ervoor zorgen dat de netbeheerder de schade altijd zelf draagt.", "De netbeheerder lijdt de schade en zal die verhalen op de aannemer; de clausule regelt de dekking daarvan."]]],
["Een schip raakt in zwaar weer in nood en de kapitein laat een deel van de lading overboord zetten om schip en overige lading te redden. Hoe heet de regeling waarbij deze opoffering over alle belanghebbenden wordt verdeeld?", [["Avarij-grosse.", "Bij avarij-grosse dragen schip en alle ladingbelanghebbenden naar verhouding bij aan opofferingen voor het gemeenschappelijk behoud; de ladingverzekering dekt die bijdrage."], ["Particuliere avarij.", "Particuliere avarij is schade die alleen een bepaalde lading of het schip treft en door de eigen belanghebbende wordt gedragen."], ["Subrogatie.", "Subrogatie is de overgang van de vordering op een aansprakelijke derde naar de verzekeraar na uitkering."], ["Abandonnement.", "Abandonnement is het afstand doen van een verzekerd object aan de verzekeraar; dat is een andere regeling."]]],
["Een exporteur kan kiezen tussen de Institute Cargo Clauses A, B en C. Welke clausules bieden de ruimste dekking voor de lading?", [["De clausules A, die een all-risksdekking bieden behoudens de uitsluitingen.", "De A-clausules dekken alle risico's van verlies of beschadiging die niet uitdrukkelijk zijn uitgesloten; B en C dekken alleen genoemde gevaren."], ["De clausules C, omdat die de meeste uitsluitingen opheffen.", "De C-clausules zijn juist de beperktste en dekken alleen een beperkt aantal genoemde gevaren, zoals brand en stranding."], ["De clausules B, omdat die tussen A en C in liggen en dus alles dekken.", "B ligt qua omvang tussen A en C, maar dekt nog steeds alleen genoemde gevaren."], ["Alle drie zijn gelijk; het verschil zit alleen in de premie.", "Er is een wezenlijk verschil in omvang van de dekking; dat verklaart ook het premieverschil."]]],
["Bij een internationaal wegtransport waarop het CMR-verdrag van toepassing is, is geen vrachtbrief opgemaakt. Wat is het gevolg?", [["De vervoerovereenkomst blijft geldig en het CMR-verdrag blijft van toepassing.", "De vrachtbrief is een bewijsmiddel; het ontbreken ervan tast het bestaan en de geldigheid van de vervoerovereenkomst niet aan."], ["De vervoerovereenkomst is nietig, zodat er geen aansprakelijkheid bestaat.", "Het verdrag bepaalt uitdrukkelijk dat de overeenkomst ook zonder vrachtbrief geldig is."], ["Het CMR is niet meer van toepassing en het nationale recht geldt volledig.", "Toepasselijkheid hangt af van het internationale karakter van het vervoer, niet van de vrachtbrief."], ["De vervoerder wordt onbeperkt aansprakelijk voor elke schade.", "Het ontbreken van een vrachtbrief leidt niet zonder meer tot onbeperkte aansprakelijkheid."]]],
["In welk geval is een CMR-vervoerder niet aansprakelijk voor beschadiging van de lading?", [["Als de schade komt door een eigen gebrek van de goederen of door onvermijdelijke omstandigheden.", "Het verdrag kent ontheffingsgronden, waaronder een eigen gebrek van de goederen en onvermijdelijke omstandigheden met onafwendbare gevolgen."], ["Als hij voor het transport een onderaannemer heeft ingeschakeld die de schade heeft veroorzaakt.", "De vervoerder is ook aansprakelijk voor de personen van wier diensten hij gebruikmaakt."], ["Als zijn vrachtwagen ouder was dan tien jaar.", "De ouderdom van het voertuig is geen ontheffingsgrond; gebreken van het voertuig komen juist voor rekening van de vervoerder."], ["Als de afzender geen transportverzekering heeft gesloten.", "Of de lading verzekerd is, verandert niets aan de aansprakelijkheid van de vervoerder."]]],
["Een transportbedrijf vervoert goederen van Rotterdam naar Groningen. Welk regime bepaalt in beginsel de aansprakelijkheid van de vervoerder?", [["Boek 8 van het BW, in de praktijk vaak aangevuld met de Algemene Vervoercondities.", "Op binnenlands wegvervoer is het CMR-verdrag niet van toepassing; het BW en de standaardvoorwaarden regelen dan de aansprakelijkheid."], ["Het CMR-verdrag, omdat dat voor alle wegvervoer in Europa geldt.", "Het CMR geldt alleen voor internationaal wegvervoer tussen verschillende landen."], ["Uitsluitend de algemene regels over onrechtmatige daad.", "Er is een vervoerovereenkomst, waarop specifieke regels voor vervoer van toepassing zijn."], ["Er is geen wettelijke regeling; partijen moeten alles zelf afspreken.", "Boek 8 BW kent wel een uitgebreide regeling voor het wegvervoer."]]],
["Een ontvanger neemt bij een CMR-transport een zending aan. Pas bij het uitpakken blijkt dat de inhoud beschadigd is, wat van buiten niet zichtbaar was. Wat moet de ontvanger doen om zijn positie te beschermen?", [["Binnen zeven dagen na aflevering, zon- en feestdagen niet meegerekend, schriftelijk voorbehoud maken.", "Bij niet-zichtbare schade geeft het verdrag deze termijn; zonder tijdig voorbehoud wordt vermoed dat de goederen in goede staat zijn ontvangen."], ["Niets; hij kan de vervoerder tot de verjaring op elk moment aanspreken zonder verdere stappen.", "Zonder tijdig voorbehoud wordt aangenomen dat de goederen goed zijn afgeleverd, wat het bewijs veel moeilijker maakt."], ["Binnen een jaar een procedure starten, omdat een voorbehoud bij verborgen schade volgens het CMR niet mogelijk is.", "Ook bij niet-zichtbare schade is een voorbehoud mogelijk en verstandig; de verjaringstermijn is iets anders."], ["Direct de goederen vernietigen om verdere schade te voorkomen.", "Het vernietigen van de goederen maakt het bewijs van de schade onmogelijk en is geen bereddingsmaatregel."]]],
["Een handelsonderneming verstuurt elke week zendingen naar klanten in binnen- en buitenland. Welke transportverzekering past hier het best?", [["Een doorlopende polis (abonnementspolis) die alle zendingen automatisch dekt.", "Met een doorlopende polis is elke zending gedekt zonder dat per keer een polis nodig is; de premie volgt uit de opgegeven waarden."], ["Voor elke zending een losse polis, die na verzending wordt aangevraagd.", "Een polis na verzending aanvragen is te laat als de schade al onderweg is ontstaan; bovendien is dit bewerkelijk."], ["Geen verzekering, omdat de vervoerder altijd voor de volle waarde aansprakelijk is.", "De aansprakelijkheid van vervoerders is vaak beperkt en kent ontheffingsgronden; de lading zelf blijft onverzekerd."], ["Een inventarisverzekering met dekking buitenshuis.", "Een inventarispolis met buitenshuisdekking is niet bedoeld voor handelszendingen in transport."]]],
["Een Nederlandse verkoper levert machines aan een Duitse koper op basis van de Incoterm EXW (af fabriek). Wie heeft tijdens het vervoer vooral belang bij een transportverzekering?", [["De koper, omdat het risico al overgaat als de goederen bij de verkoper klaarstaan.", "Bij EXW draagt de koper vanaf de terbeschikkingstelling bij de verkoper het risico van verlies en beschadiging, dus ook tijdens het vervoer."], ["De verkoper, omdat hij tot aflevering bij de koper het risico draagt.", "Dat geldt bij leveringsvoorwaarden waarbij de verkoper tot de bestemming levert; bij EXW gaat het risico vroeg over."], ["De vervoerder, omdat die tijdens het transport de eigenaar van de vervoerde goederen wordt.", "Een vervoerder wordt geen eigenaar van de lading; hij heeft alleen een vervoersverplichting."], ["Niemand, omdat EXW een verzekering door de verkoper verplicht stelt.", "Bij EXW heeft de verkoper geen verzekeringsplicht; die verplichting kennen bijvoorbeeld CIF en CIP."]]],
["Wie is op grond van de WAM verplicht om een motorrijtuig verzekerd te hebben?", [["De bezitter of houder, in de praktijk meestal de kentekenhouder.", "De wet legt de verzekeringsplicht bij bezitter of houder; de RDW controleert die plicht aan de hand van het kenteken."], ["Uitsluitend de bestuurder die op dat moment rijdt.", "De bestuurder is wel meeverzekerd, maar de verzekeringsplicht rust op bezitter of houder."], ["De werkgever van iedere werknemer die zakelijk met een motorrijtuig rijdt.", "Een werkgever is alleen verzekeringsplichtig als hij bezitter of houder van het voertuig is."], ["De leverancier die het voertuig heeft verkocht.", "Na de verkoop is de leverancier geen bezitter of houder meer en draagt hij die plicht niet."]]],
["Een installatiebedrijf heeft dure gereedschappen en materialen in zijn bestelbussen liggen. Bij een inbraak in een bus worden ze gestolen. Is dit doorgaans gedekt op de cascoverzekering van de bus?", [["Meestal niet; lading en gereedschap moeten apart worden verzekerd.", "De casco dekt het voertuig zelf en vaste accessoires; losse inhoud valt daar doorgaans buiten."], ["Ja, omdat alles wat zich in het voertuig bevindt onder de casco valt.", "Casco ziet op het voertuig; voor de inhoud is een aparte dekking nodig."], ["Ja, mits de bus WA-casco is verzekerd in plaats van allrisk.", "Een beperktere cascodekking maakt de dekking voor lading niet ruimer."], ["Nee, omdat gereedschap in een bus wettelijk niet verzekerbaar is.", "Gereedschap in een voertuig is wel verzekerbaar, al stellen verzekeraars vaak eisen aan beveiliging."]]],
["Een werknemer gebruikt met toestemming de bedrijfsauto in het weekend privé en veroorzaakt een aanrijding met een ander voertuig. Is de schade van de tegenpartij gedekt op de WAM-polis van de werkgever?", [["Ja, de WAM-polis dekt iedere bestuurder die met toestemming rijdt, ook bij privégebruik.", "De WAM beschermt verkeersslachtoffers; de verzekerde aansprakelijkheid is niet beperkt tot zakelijke ritten."], ["Nee, de WAM-polis van een bedrijf dekt uitsluitend zakelijke ritten.", "De WAM-dekking is gekoppeld aan het motorrijtuig en de bestuurders ervan, niet aan het doel van de rit."], ["Nee, de werknemer moet voor privéritten met een bedrijfsauto zelf een WAM-verzekering hebben.", "Er hoeft geen tweede WAM-verzekering te zijn; het voertuig is al verzekerd."], ["Alleen als de werknemer niet schuldig is aan de aanrijding.", "Juist als de bestuurder aansprakelijk is, dekt de WAM-polis de schade van de tegenpartij."]]],
["Wat is de functie van de groene kaart (internationaal verzekeringsbewijs) bij een wagenpark dat in het buitenland rijdt?", [["Het is een internationaal erkend bewijs dat er een geldige WA-verzekering is.", "De groene kaart toont in de deelnemende landen aan dat het voertuig verzekerd is; binnen de EU geldt het kenteken in beginsel als bewijs."], ["Het is een aanvullende cascodekking voor schade aan de eigen auto in het buitenland.", "De groene kaart zegt niets over casco; zij bewijst de WA-dekking."], ["Het is een vergunning om in het buitenland goederen te vervoeren.", "Voor beroepsgoederenvervoer gelden andere vergunningen; de groene kaart is een verzekeringsbewijs."], ["Het is een milieukeurmerk dat toegang geeft tot buitenlandse milieuzones.", "Milieuzones kennen hun eigen registraties en stickers; de groene kaart staat daar los van."]]],
["Welk onderdeel van een cyberverzekering blijkt bij een ransomware-aanval vaak het meest waardevol voor een mkb-bedrijf?", [["Directe incidentrespons door IT-forensische, juridische en communicatiespecialisten.", "Snel deskundige hulp beperkt de stilstand en schade; veel mkb-bedrijven hebben die kennis zelf niet in huis."], ["De vergoeding van de waardevermindering van de computers.", "De apparatuur blijft bij ransomware vaak intact; het probleem zit in de versleutelde data en stilstand."], ["De dekking voor diefstal van laptops en telefoons van medewerkers uit een geparkeerde bedrijfsauto.", "Diefstal van hardware is een zaakrisico en hoort niet tot de kern van een cyberincident."], ["De premiekorting bij het melden van het incident.", "Melden levert geen premiekorting op; het gaat om de hulp en vergoeding na het incident."]]],
["Klanten stellen een webwinkel aansprakelijk voor schade nadat hun gegevens bij een hack zijn gelekt. Waarom biedt de AVB hiervoor doorgaans geen dekking?", [["De AVB dekt vooral personen- en zaakschade; dit is vermogensschade door een datalek.", "Data gelden niet als zaak en een datalek leidt tot vermogensschade; daarom is voor dit risico een cyberverzekering met aansprakelijkheidsdekking nodig."], ["De AVB dekt nooit schade van klanten van het bedrijf, alleen schade van toevallige voorbijgangers.", "Ook klanten zijn derden; het probleem is de aard van de schade, niet wie de benadeelde is."], ["De AVB keert alleen uit als de webwinkel zelf de hack heeft gepleegd.", "Opzet van de verzekerde is juist uitgesloten; dat verklaart de ontbrekende dekking niet."], ["Een datalek valt altijd onder de rechtsbijstandverzekering van de klant.", "De rechtsbijstand van de klant helpt hem bij het verhaal, maar dekt niet de aansprakelijkheid van de webwinkel."]]],
["Hoe gaan cyberpolissen doorgaans om met boetes die een toezichthouder als de Autoriteit Persoonsgegevens oplegt na een datalek?", [["Die zijn vaak uitgesloten of alleen gedekt voor zover ze wettelijk verzekerbaar zijn.", "De verzekerbaarheid van bestuurlijke boetes is beperkt; een boete is bedoeld om de overtreder zelf te treffen."], ["Die worden altijd volledig vergoed, omdat ze het rechtstreekse gevolg zijn van een gedekt incident.", "Een gedekt incident maakt een boete niet automatisch verzekerbaar; polissen beperken dit."], ["Die worden vergoed door de Autoriteit Persoonsgegevens zelf als het bedrijf meewerkt.", "Een toezichthouder vergoedt geen boetes; medewerking kan hooguit de hoogte beïnvloeden."], ["Die vallen onder de D&O-dekking van de onderneming zelf.", "D&O dekt aanspraken op bestuurders; boetes aan de onderneming zijn daarmee niet gedekt."]]],
["De systemen van een accountantskantoor liggen twee dagen plat doordat de cloudleverancier zelf is gehackt. Het kantoor zelf is niet gehackt. Wat is voor de dekking op de cyberpolis van het kantoor van belang?", [["Of de polis ook bedrijfsschade dekt door uitval bij een externe IT-dienstverlener.", "Veel polissen dekken alleen incidenten in eigen systemen; afhankelijkheid van een externe leverancier vraagt een uitbreiding."], ["Of het kantoor op de dag van de uitval zelf aangifte heeft gedaan bij de politie tegen onbekenden.", "Aangifte kan verstandig zijn, maar bepaalt niet of uitval bij een leverancier onder de dekking valt."], ["Of de cloudleverancier in Nederland is gevestigd.", "De vestigingsplaats van de leverancier is voor de dekking niet de beslissende vraag."], ["Niets, omdat elke vorm van IT-uitval automatisch is gedekt.", "Dekking is niet onbeperkt; de polis bepaalt welke oorzaken van uitval verzekerd zijn."]]],
["Een salarisverwerker verwerkt persoonsgegevens in opdracht van werkgevers. Bij de salarisverwerker vindt een datalek plaats. Wie moet het lek melden bij de Autoriteit Persoonsgegevens?", [["De werkgever als verwerkingsverantwoordelijke; de verwerker meldt het lek aan de werkgever.", "De AVG legt de meldplicht bij de verwerkingsverantwoordelijke; de verwerker moet deze zo snel mogelijk informeren."], ["Alleen de salarisverwerker, omdat het lek in zijn eigen systemen plaatsvond en hij de gegevens beheert.", "De verwerker is wel betrokken, maar de wettelijke meldplicht aan de AP rust op de verwerkingsverantwoordelijke."], ["De werknemers van wie de gegevens zijn gelekt.", "Betrokkenen hebben geen meldplicht; zij moeten soms juist door de verwerkingsverantwoordelijke worden geïnformeerd."], ["Niemand, omdat salarisgegevens geen persoonsgegevens zijn.", "Salarisgegevens zijn wel degelijk persoonsgegevens, vaak zelfs gevoelig van aard."]]],
["Wanneer moet een organisatie na een datalek ook de betrokkenen zelf informeren, naast de melding aan de Autoriteit Persoonsgegevens?", [["Als het lek waarschijnlijk een hoog risico oplevert voor hun rechten en vrijheden.", "Bij een hoog risico moeten betrokkenen worden ingelicht, zodat zij zelf maatregelen kunnen nemen, zoals alert zijn op phishing."], ["Altijd, ook als het risico voor betrokkenen te verwaarlozen is.", "Bij een gering risico hoeft betrokkenen niet altijd te worden geïnformeerd; de plicht is risicogebaseerd."], ["Nooit; de Autoriteit Persoonsgegevens informeert de betrokkenen zelf.", "De verantwoordelijkheid ligt bij de organisatie zelf, niet bij de toezichthouder."], ["Alleen als de cyberverzekeraar daarvoor toestemming geeft.", "De wettelijke informatieplicht hangt niet af van de verzekeraar; die kan wel helpen met de uitvoering."]]],
["Wat is de wachttijd die veel zakelijke rechtsbijstandverzekeringen kennen?", [["Een periode na ingang waarin voor bepaalde geschillen nog geen dekking bestaat.", "De wachttijd voorkomt dat iemand een verzekering sluit zodra hij een conflict ziet aankomen, ook als dat nog niet voorzienbaar was."], ["De tijd die de verzekeraar heeft om een advocaat in te schakelen.", "Dat is een behandeltermijn; de wachttijd gaat over het moment vanaf wanneer dekking bestaat."], ["De periode waarin een vonnis nog niet ten uitvoer kan worden gelegd.", "Dat is een procesrechtelijke kwestie en geen onderdeel van de polis."], ["De periode na het einde van de polis waarin nog schade bij de verzekeraar kan worden gemeld.", "Dat is een uitloopperiode; de wachttijd ligt aan het begin van de verzekering."]]],
["Een groothandel wil een rechtsbijstandverzekering vooral gebruiken om onbetaalde facturen te innen waarover de klant geen inhoudelijk geschil heeft. Wat is juist?", [["Incasso van onbetwiste vorderingen is doorgaans niet of maar beperkt gedekt.", "Rechtsbijstand is bedoeld voor juridische geschillen; voor het innen van onbetwiste facturen is een incassodienst of kredietverzekering geschikter."], ["Incasso is altijd volledig gedekt, omdat het om een juridische vordering gaat.", "Juist onbetwiste vorderingen zijn vaak uitgesloten of slechts beperkt gedekt."], ["Incasso is gedekt, maar alleen als de factuur hoger is dan het eigen risico van de AVB.", "Het eigen risico van een andere polis heeft geen invloed op de dekking van de rechtsbijstandpolis."], ["Incasso is gedekt als de klant in het buitenland is gevestigd.", "De vestigingsplaats van de debiteur verandert niets aan de aard van een onbetwiste vordering."]]],
["Een rechtsbijstandverzekeraar vindt een zaak kansloos, terwijl de verzekerde wil doorprocederen. Wat bieden veel rechtsbijstandpolissen in die situatie?", [["Een geschillenregeling: een externe advocaat geeft op kosten van de verzekeraar een oordeel.", "Zo kan de verzekerde een onafhankelijk oordeel krijgen over de haalbaarheid; volgt de verzekeraar dat oordeel, dan gaat de behandeling verder."], ["Geen enkele mogelijkheid; het oordeel van de verzekeraar over de haalbaarheid is altijd bindend.", "Polissen bieden juist een regeling voor dit soort meningsverschillen, onder meer om belangenconflicten te voorkomen."], ["Een automatische uitkering van de helft van het financiële belang.", "Afkoop van het belang is een andere regeling; hier gaat het om het verschil van mening over de aanpak."], ["Een verplichte verwijzing naar de Ondernemingskamer.", "De Ondernemingskamer behandelt vennootschapsrechtelijke geschillen en is niet bedoeld voor meningsverschillen met een verzekeraar."]]],
["Een klant van een aannemer stelt de aannemer aansprakelijk voor schade aan zijn woning. Welke polis van de aannemer is in eerste instantie aangewezen om het verweer te voeren?", [["De AVB, omdat de aansprakelijkheidsverzekeraar ook het verweer voert.", "Een aansprakelijkheidsverzekeraar beoordeelt de aanspraak, voert verweer en betaalt als de aanspraak terecht is."], ["De rechtsbijstandverzekering, omdat elk juridisch conflict daaronder valt.", "Verweer tegen een aansprakelijkstelling die op de AVB is gedekt, hoort bij de aansprakelijkheidsverzekeraar; rechtsbijstand sluit dit vaak uit."], ["De CAR-verzekering van de klant.", "De klant heeft geen CAR-polis voor het werk van de aannemer, en die zou ook niet het verweer van de aannemer voeren."], ["De opstalverzekering van de aannemer.", "Een opstalpolis dekt schade aan het eigen gebouw van de aannemer, geen aansprakelijkheid."]]],
["Een ondernemer wordt verdacht van een opzetdelict en vraagt rechtsbijstand bij zijn strafzaak. Hoe regelen veel rechtsbijstandpolissen dit?", [["Dekking volgt vaak pas achteraf, als de verzekerde wordt vrijgesproken.", "Verzekeraars willen geen opzet financieren; bij vrijspraak of ontslag van rechtsvervolging worden de kosten alsnog vergoed."], ["De kosten zijn altijd vooraf volledig gedekt, ongeacht de uitkomst.", "Bij opzetdelicten is dekking vooraf meestal juist uitgesloten; de afloop van de zaak is bepalend."], ["De verzekeraar betaalt ook een eventuele boete als de ondernemer wordt veroordeeld.", "Strafrechtelijke boetes zijn niet verzekerbaar; zij moeten de dader zelf treffen."], ["Strafzaken kunnen nooit onder een rechtsbijstandverzekering vallen.", "Veel polissen bieden wel strafrechtsbijstand, zij het met beperkingen bij opzet."]]],
["Wie draagt bij een verzekering die via een gevolmachtigd agent is gesloten het verzekeringstechnische risico?", [["De verzekeraar die de volmacht heeft verleend.", "De gevolmachtigde handelt namens de verzekeraar; het risico en de verplichting tot uitkeren liggen bij die verzekeraar."], ["De gevolmachtigde zelf, omdat hij het risico heeft geaccepteerd.", "Accepteren namens een ander maakt de gevolmachtigde nog geen risicodrager."], ["De adviseur die de klant heeft doorverwezen naar de gevolmachtigde.", "Een adviseur draagt geen verzekeringstechnisch risico; hij kan wel aansprakelijk zijn voor een adviesfout."], ["De verzekeringnemer, totdat de verzekeraar de polis heeft goedgekeurd.", "Na acceptatie door de gevolmachtigde is de verzekeraar gebonden; er is geen extra goedkeuring nodig."]]],
["Heeft een gevolmachtigd agent die zakelijke schadeverzekeringen accepteert een vergunning van de AFM nodig?", [["Ja, optreden als gevolmachtigd agent is vergunningplichtig onder de Wft.", "De Wft rekent het optreden als gevolmachtigd agent tot de vergunningplichtige financiële diensten."], ["Nee, omdat de verzekeraar al een vergunning van DNB heeft.", "De vergunning van de verzekeraar dekt niet de eigen dienstverlening van de gevolmachtigde."], ["Nee, zolang de gevolmachtigde alleen zakelijke klanten en geen consumenten bedient.", "Ook bij dienstverlening aan zakelijke klanten geldt in beginsel de vergunningplicht."], ["Alleen als de gevolmachtigde ook schades afhandelt.", "De vergunningplicht volgt al uit het accepteren namens de verzekeraar."]]],
["Een gevolmachtigde accepteert een risico dat buiten de grenzen van zijn volmacht valt. De verzekeringnemer wist dat niet en mocht op de acceptatie vertrouwen. Wat is juist?", [["De verzekeraar kan gebonden zijn door gerechtvaardigd vertrouwen en de gevolmachtigde intern aanspreken.", "Bij schijn van vertegenwoordigingsbevoegdheid wordt de derde beschermd; het overschrijden van de volmacht is een zaak tussen verzekeraar en gevolmachtigde."], ["De verzekering is altijd nietig, omdat de gevolmachtigde onbevoegd was.", "Het BW beschermt een derde die redelijkerwijs op de bevoegdheid mocht vertrouwen."], ["De gevolmachtigde wordt zelf verzekeraar van het risico.", "Een gevolmachtigde is geen verzekeraar; hij kan hooguit aansprakelijk zijn tegenover de verzekeraar of de klant."], ["De verzekeringnemer moet de schade zelf dragen, omdat hij de grenzen van de volmacht had moeten controleren.", "Een verzekeringnemer hoeft de interne afspraken tussen verzekeraar en gevolmachtigde niet te kennen."]]],
["Een gevolmachtigde ontwikkelt binnen zijn volmacht een eigen pakketpolis voor bakkerijen en bepaalt zelf de dekking en voorwaarden. Welke IDD-regels zijn daarbij voor hem relevant?", [["De regels voor productgoedkeuring en -beoordeling, omdat hij mede productontwikkelaar is.", "Wie wezenlijke kenmerken van een product bepaalt, geldt als (mede)ontwikkelaar en moet onder meer een doelmarkt vaststellen en het product toetsen."], ["Geen, omdat de IDD alleen geldt voor levensverzekeringen.", "De IDD geldt voor alle verzekeringsdistributie, dus ook voor schadeverzekeringen."], ["Alleen de regels voor de vakbekwaamheid van zijn medewerkers.", "Vakbekwaamheid geldt ook, maar bij eigen productontwikkeling komen de productregels nadrukkelijk in beeld."], ["Alleen de regels die gelden voor verzekeraars met een vergunning van De Nederlandsche Bank.", "Een gevolmachtigde heeft geen vergunning als verzekeraar; de productregels gelden voor hem als ontwikkelaar."]]],
["Waarom voert een verzekeraar periodiek audits uit bij zijn gevolmachtigden?", [["Omdat hij verantwoordelijk blijft voor wat namens hem gebeurt, zoals acceptatie en schadebehandeling.", "Uitbesteden van werkzaamheden ontslaat de verzekeraar niet van zijn eigen verantwoordelijkheid; toezicht is onderdeel van een beheerste bedrijfsvoering."], ["Omdat de gevolmachtigde anders zijn provisie niet uitbetaald mag krijgen.", "Provisie hangt af van de contractuele afspraken; de audit dient de beheersing van het risico."], ["Omdat de AFM de verzekeraar verplicht elke polis van de gevolmachtigde achteraf zelf opnieuw te accepteren.", "Dan zou de volmacht geen zin hebben; de verzekeraar houdt toezicht, maar accepteert niet alles opnieuw."], ["Omdat de gevolmachtigde het risico van de polissen draagt en dat moet worden gecontroleerd.", "Het risico ligt juist bij de verzekeraar; daarom heeft die belang bij goede controle."]]],
["Wat onderscheidt een assurantiemakelaar in de klassieke zin van een agent?", [["De makelaar handelt in opdracht van de klant, de agent op basis van een agentuurovereenkomst met verzekeraars.", "De makelaar behartigt primair de belangen van de verzekeringnemer; de agent heeft een nauwere band met de verzekeraars die hij vertegenwoordigt."], ["De makelaar mag uitsluitend levensverzekeringen bemiddelen en de agent uitsluitend schade- en zorgverzekeringen.", "Het onderscheid gaat niet over productsoorten; beide kunnen in schade en leven bemiddelen."], ["De makelaar draagt zelf het risico van de verzekeringen die hij plaatst.", "Een makelaar is geen verzekeraar en draagt geen verzekeringstechnisch risico."], ["De makelaar heeft geen Wft-vergunning nodig, de agent wel.", "Beide bemiddelen in verzekeringen en zijn in beginsel vergunningplichtig."]]],
["Waarom sluit een verzekeraar zelf herverzekering af?", [["Om zijn eigen behoud per risico of gebeurtenis te beperken en meer capaciteit te kunnen bieden.", "Door een deel van grote risico's door te geven, kan de verzekeraar grote polissen accepteren zonder dat één schade zijn vermogen bedreigt."], ["Om de verzekeringnemer een rechtstreekse vordering op een tweede verzekeraar te geven.", "Bij herverzekering heeft de verzekeringnemer in beginsel geen vordering op de herverzekeraar."], ["Om aan de verzekeringnemer een lagere premie te kunnen garanderen.", "Herverzekering kost de verzekeraar ook premie; een lagere premie voor de klant is geen vast gevolg."], ["Omdat de wet verbiedt dat een verzekeraar meer dan één risico per sector draagt.", "Een dergelijk wettelijk verbod bestaat niet; herverzekering is een keuze in het risicobeheer."]]],
["Waarom werken polissen op de beursmarkt vaak met door de markt vastgestelde standaardcondities?", [["Zodat alle deelnemers dezelfde voorwaarden hanteren en de dekking voor iedereen helder is.", "Bij meerdere verzekeraars op één risico voorkomen uniforme voorwaarden discussie over verschillen tussen de aandelen."], ["Omdat afwijkende voorwaarden op de beursmarkt wettelijk verboden zijn.", "Maatwerk is op de beursmarkt juist goed mogelijk; standaardcondities zijn een basis, geen verbod op afwijken."], ["Omdat de leidende verzekeraar het volledige risico anders alleen voor eigen rekening moet nemen.", "De verdeling van het risico volgt uit de aandelen, niet uit het gebruik van standaardcondities."], ["Omdat standaardcondities de zorgplicht van de makelaar wegnemen.", "De makelaar moet ook bij standaardcondities beoordelen of de dekking past bij het risico van de klant."]]],
["Een groothandel levert op rekening aan honderden zakelijke afnemers en vreest voor wanbetaling bij faillissementen. Welke verzekering sluit hier het best op aan?", [["Een kredietverzekering, waarbij de verzekeraar per afnemer een kredietlimiet vaststelt.", "De kredietverzekering dekt het debiteurenrisico bij insolventie of langdurige wanbetaling, binnen de door de verzekeraar goedgekeurde limieten."], ["Een bedrijfsschadeverzekering op basis van de brutowinst.", "Bedrijfsschade vergoedt winstderving na materiële schade, geen onbetaalde facturen."], ["Een rechtsbijstandverzekering met dekking voor alle incasso's, ook bij faillissement van afnemers.", "Rechtsbijstand dekt incasso van onbetwiste vorderingen doorgaans niet, en zeker niet het verlies bij insolventie."], ["Een D&O-verzekering voor de bestuurders van de afnemers.", "De groothandel is geen verzekeringnemer van zo'n polis en de D&O dekt geen handelsvorderingen."]]],
["Een bv betaalt de premie van haar AVB niet op de vervaldag. Vanaf wanneer bestaat volgens het BW in beginsel geen dekking meer?", [["Als niet is betaald binnen veertien dagen na een aanmaning na de vervaldag.", "De verzekeraar moet eerst aanmanen en de gevolgen noemen; pas als ook daarna niet tijdig wordt betaald, kan de dekking worden geschorst."], ["Direct op de vervaldag, zonder dat een aanmaning nodig is.", "Voor schorsing van de dekking is in beginsel eerst een aanmaning na de vervaldag vereist."], ["Pas als de verzekeraar de verzekering schriftelijk en met redenen heeft opgezegd.", "Schorsing van dekking na aanmaning is iets anders dan opzegging; de verzekering kan blijven bestaan terwijl de dekking is geschorst."], ["Na drie maanden, ongeacht of de verzekeraar heeft aangemaand.", "Een vaste termijn van drie maanden zonder aanmaning bestaat niet in de wet."]]],
["Binnen welke termijn verjaart volgens het BW in beginsel een rechtsvordering tot uitkering uit een schadeverzekering?", [["Drie jaar vanaf de dag nadat de gerechtigde met de opeisbaarheid bekend werd.", "De wet kent voor uitkeringsvorderingen uit verzekering een eigen verjaringstermijn, die kan worden gestuit door een schriftelijke aanspraak."], ["Vijf jaar vanaf de dag waarop de schade is ontstaan, net als bij andere schadevergoeding.", "Vijf jaar is de algemene termijn voor vorderingen tot schadevergoeding; voor uitkeringen uit verzekering geldt een eigen regeling."], ["Eén jaar na de schadedatum, net als bij het CMR-verdrag.", "De CMR-termijn geldt voor vorderingen uit internationaal wegvervoer, niet voor uitkeringen uit verzekering."], ["Twintig jaar na het sluiten van de verzekering.", "Een termijn van twintig jaar komt in het BW voor als absolute termijn bij schadevergoeding, niet bij verzekeringsuitkeringen."]]],
["Een ondernemer meldt een waterschade pas drie maanden na ontdekking. De verzekeraar kan de oorzaak daardoor niet meer goed vaststellen. Wat is volgens het BW in beginsel het gevolg?", [["De verzekeraar kan de uitkering verminderen met de schade die hij door de late melding lijdt.", "De wet laat het niet-tijdig melden doorwerken voor zover de verzekeraar in zijn belang is geschaad; volledig verval vereist meer."], ["De verzekeraar hoeft nooit meer uit te keren, ongeacht of hij daardoor nadeel lijdt.", "Verval van het hele recht is alleen mogelijk als dat is bedongen en de verzekeraar in een redelijk belang is geschaad."], ["Een late melding heeft geen enkel gevolg, zolang de schade binnen de verjaringstermijn is gemeld.", "De meldingsplicht is een eigen verplichting; schending ervan kan wel tot vermindering leiden."], ["De verzekeraar mag de polis met terugwerkende kracht beëindigen.", "Te laat melden geeft geen recht om de verzekering met terugwerkende kracht te beëindigen."]]],
["Bij een inbraakschade dient een ondernemer bewust een lijst in met zaken die nooit aanwezig waren, om meer uitgekeerd te krijgen. Wat is in beginsel het gevolg?", [["Het recht op uitkering vervalt geheel, tenzij de misleiding dat verval niet rechtvaardigt.", "Bij opzet om de verzekeraar te misleiden vervalt elk recht op uitkering; daarnaast kan de verzekeraar de polis beëindigen en de fraude registreren."], ["Alleen het opgeblazen deel van de claim wordt niet uitgekeerd; de echte schade wordt wel vergoed.", "De wet laat bij opzettelijke misleiding het gehele recht vervallen, niet alleen het overdreven deel."], ["De verzekeraar mag alleen de premie verhogen voor het volgende jaar.", "Opzettelijke misleiding heeft verdergaande gevolgen dan een premieverhoging."], ["Er is geen gevolg zolang de inbraak zelf echt heeft plaatsgevonden.", "Ook als de gebeurtenis echt is, leidt opzettelijk overdrijven van de schade tot verval van recht."]]],
["Een ondernemer steekt zijn eigen loods in brand om de verzekeringsuitkering op te strijken. Wat bepaalt het BW over deze schade?", [["De verzekeraar keert niet uit bij schade die de verzekerde met opzet of roekeloos veroorzaakte.", "Een verzekering is bedoeld voor onzekere gebeurtenissen; opzettelijk of roekeloos veroorzaakte schade valt daarbuiten."], ["De verzekeraar keert uit, maar mag het bedrag later terugvorderen bij de brandweer.", "De brandweer heeft niets met de aansprakelijkheid voor opzettelijke brandstichting te maken."], ["De verzekeraar keert de helft uit, omdat ook een opzettelijk gestichte brand een gedekte gebeurtenis is.", "Er is geen gedeeltelijke uitkering; opzettelijk veroorzaakte schade is volledig van uitkering uitgesloten."], ["De verzekeraar moet uitkeren als de polis geen opzetuitsluiting bevat.", "De wet sluit opzet zelf al uit; daar is geen polisbepaling voor nodig."]]],
["Een partij voedingsmiddelen in een opslag bederft door de eigen aard van het product, zonder invloed van buitenaf. Wat bepaalt het BW hierover als de polis niets regelt?", [["Schade door eigen gebrek van de zaak wordt niet vergoed, tenzij anders is afgesproken.", "Eigen gebrek is een eigenschap van de zaak die schade veroorzaakt zonder externe oorzaak; de wet sluit die schade uit, maar partijen kunnen anders afspreken."], ["Schade door eigen gebrek wordt altijd vergoed, omdat de zaak verzekerd is.", "De wet gaat juist uit van uitsluiting van eigen gebrek, tenzij de polis dekking biedt."], ["Schade door eigen gebrek mag wettelijk nooit worden meeverzekerd.", "De uitsluiting is van regelend recht; partijen kunnen dekking voor eigen gebrek overeenkomen."], ["Schade door eigen gebrek valt altijd onder de aansprakelijkheid van de leverancier of producent.", "Of de leverancier aansprakelijk is, hangt af van de koopovereenkomst; het staat los van de vraag wat de polis dekt."]]],
["Een ondernemer sluit op maandag een inventarisverzekering, terwijl hij weet dat zijn bedrijfsruimte in het weekend al is overstroomd. Hij meldt die schade daarna bij de verzekeraar. Wat is juist?", [["Geen dekking, omdat een verzekering onzekerheid vereist en de schade al vaststond.", "De wet vereist bij het sluiten onzekerheid over het ontstaan van schade; een schade die al is ontstaan en bekend is, valt buiten de verzekering."], ["Er is dekking, omdat de schade binnen de eerste week van de verzekering is gemeld.", "Het tijdstip van melden is niet beslissend; het gaat om het ontbreken van onzekerheid bij het sluiten."], ["Er is dekking, maar de verzekeraar mag een hoger eigen risico toepassen.", "Een hoger eigen risico lost het ontbreken van onzekerheid niet op; de schade valt er geheel buiten."], ["Er is dekking, omdat de verzekeraar geen vragen heeft gesteld over eerdere schade.", "De onzekerheidseis geldt los van de vragenlijst; ook zonder vraag is een al bekende schade niet gedekt."]]],
["Een bv heeft een zakelijke inventarisverzekering die na het eerste jaar stilzwijgend wordt verlengd. Geldt de wettelijke regel dat een consument na stilzwijgende verlenging op elk moment met een termijn van een maand kan opzeggen ook voor deze bv?", [["Nee, die regel geldt alleen voor consumenten; voor de bv gelden de polisafspraken.", "De maandelijkse opzegmogelijkheid na verlenging beschermt verzekeringnemers die als natuurlijk persoon niet in beroep of bedrijf handelen; bij zakelijke polissen bepalen de voorwaarden wanneer kan worden opgezegd."], ["Ja, die regel geldt voor iedere verzekeringnemer, zakelijk of particulier.", "De opzegregel na stilzwijgende verlenging is uitdrukkelijk beperkt tot consumenten."], ["Ja, maar alleen als de bv minder dan tien werknemers heeft.", "De wet maakt geen onderscheid naar het aantal werknemers; het gaat om de vraag of de verzekeringnemer consument is."], ["Nee, een zakelijke verzekering kan na verlenging nooit tussentijds worden opgezegd.", "Tussentijds opzeggen kan wel, als de voorwaarden dat toestaan, bijvoorbeeld na een schade of premiewijziging."]]],
["Wat houdt de IDD-eis van productgoedkeuring en -beoordeling (POG) voor een verzekeraar in?", [["Per product een doelmarkt vaststellen, het product daarop toetsen en een passende distributie kiezen.", "Zo moet het product aansluiten bij de behoeften van de klanten voor wie het bedoeld is, ook nadat het op de markt is gebracht."], ["Elk nieuw product vooraf ter goedkeuring voorleggen aan de AFM voordat het in de markt mag worden verkocht.", "De AFM keurt producten niet vooraf goed; de verzekeraar moet zelf een productgoedkeuringsproces hebben."], ["Alleen controleren of de premie concurrerend is ten opzichte van andere aanbieders.", "Premie speelt een rol, maar POG gaat om de waarde en geschiktheid van het product voor de doelmarkt."], ["Uitsluitend levensverzekeringen met een beleggingscomponent beoordelen.", "De productregels gelden voor alle verzekeringsproducten, ook voor schadeverzekeringen."]]],
["Een adviseur zegt tegen zijn zakelijke klant dat hij adviseert op basis van een onpartijdige analyse van de markt. Wat vraagt de IDD dan van hem?", [["Dat hij een voldoende groot aantal producten op de markt beoordeelt.", "Wie zich op een onpartijdige analyse beroept, mag zich niet beperken tot één of enkele verzekeraars; de vergelijking moet representatief zijn."], ["Dat hij uitsluitend producten van verzekeraars waarmee hij een agentuurovereenkomst heeft vergelijkt.", "Een beperkte selectie past niet bij de claim van een onpartijdige analyse van de markt."], ["Dat hij geen enkele vorm van beloning ontvangt voor zijn advies.", "Een onpartijdige analyse gaat over de breedte van het onderzoek, niet over het ontbreken van beloning."], ["Dat hij altijd het goedkoopste product adviseert.", "Het passende product is niet automatisch het goedkoopste; dekking en voorwaarden wegen mee."]]],
["Een adviseur helpt zijn zakelijke klant na een brand met het indienen en onderbouwen van de claim bij de verzekeraar. Valt dit onder verzekeringsdistributie in de zin van de IDD?", [["Ja, ook bijstand bij de uitvoering van de verzekering, zoals bij een schade, valt eronder.", "De IDD omschrijft distributie ruim; naast adviseren en sluiten hoort ook hulp bij een claim erbij."], ["Nee, de IDD gaat alleen over het advies vooraf en het moment van sluiten van de verzekering zelf.", "De definitie loopt door na het sluiten; ook de uitvoering van het contract hoort erbij."], ["Nee, schadebehandeling valt altijd onder de Wwft.", "De Wwft ziet op witwassen en terrorismefinanciering, niet op hulp bij het indienen van een claim."], ["Alleen als de adviseur daarvoor een afzonderlijke declaratie stuurt.", "De wijze van beloning bepaalt niet of de werkzaamheid onder de definitie valt."]]],
["Welke vakbekwaamheid is voor een adviseur vereist om zakelijke klanten te adviseren over schadeverzekeringen zoals AVB en brandverzekeringen?", [["Wft Basis en Wft Schadeverzekeringen Zakelijk, actueel gehouden via PE.", "Voor elk adviesgebied gelden eigen modules; na het behalen moeten adviseurs hun kennis actueel houden via permanente educatie."], ["Alleen het diploma Wft Schadeverzekeringen Particulier, omdat de producten vergelijkbaar zijn.", "Particuliere en zakelijke schadeverzekeringen zijn afzonderlijke adviesgebieden met een eigen diploma."], ["Geen Wft-diploma, omdat zakelijke klanten zelf deskundig worden geacht.", "Ook bij advies aan zakelijke klanten geldt de vakbekwaamheidseis van de Wft."], ["Een diploma rechten, omdat aansprakelijkheid een juridisch onderwerp is.", "Een juridische opleiding vervangt de Wft-diploma's niet."]]],
["Waar moeten Nederlandse vennootschappen hun uiteindelijk belanghebbenden (UBO's) registreren?", [["In het UBO-register dat wordt gehouden door de Kamer van Koophandel.", "Het UBO-register is ondergebracht bij het Handelsregister van de KvK; Wwft-instellingen gebruiken het bij hun cliëntenonderzoek."], ["Bij de Belastingdienst, als onderdeel van de vennootschapsbelastingaangifte.", "De aangifte vennootschapsbelasting is iets anders dan de wettelijke registratie van UBO's."], ["Bij De Nederlandsche Bank, die het register voor alle ondernemingen bijhoudt.", "DNB houdt toezicht op financiële instellingen, maar beheert het UBO-register niet."], ["Uitsluitend in de eigen administratie van de vennootschap, zonder centrale registratie.", "De wet vereist naast eigen administratie een registratie in een centraal UBO-register."]]],
["Bij het cliëntenonderzoek naar een stichting kan na grondig onderzoek geen natuurlijk persoon worden gevonden die als UBO kwalificeert. Wie wordt dan als UBO aangemerkt?", [["Het hoger leidinggevend personeel, zoals de bestuurders (de pseudo-UBO).", "Als geen echte UBO kan worden vastgesteld, valt de Wwft terug op degenen die de organisatie feitelijk leiden."], ["Niemand; het cliëntenonderzoek kan dan worden afgesloten zonder UBO.", "De wet vraagt in dat geval juist om registratie van een pseudo-UBO."], ["De notaris die de stichting heeft opgericht.", "Een notaris is geen belanghebbende en heeft geen zeggenschap over de stichting."], ["De grootste donateur van de stichting.", "Een donateur heeft doorgaans geen eigendom of zeggenschap; dat maakt hem geen UBO."]]],
["Uit het cliëntenonderzoek van een Wwft-instelling blijkt dat de UBO van een zakelijke klant een politiek prominent persoon (PEP) is. Wat is het gevolg?", [["Er geldt verscherpt cliëntenonderzoek, onder meer naar de herkomst van het vermogen.", "Een PEP heeft een verhoogd risico op corruptie; de wet vraagt extra maatregelen, zoals goedkeuring door hoger leidinggevenden, maar verbiedt de relatie niet."], ["De relatie moet direct worden beëindigd, omdat met PEP's geen zaken mogen worden gedaan.", "Een PEP-status leidt tot extra onderzoek, niet tot een verbod op dienstverlening."], ["De klant moet worden gemeld als ongebruikelijke transactie bij de FIU.", "Een PEP-status is op zichzelf geen ongebruikelijke transactie; melden is pas aan de orde bij een concrete indicatie."], ["Er geldt vereenvoudigd cliëntenonderzoek, omdat een PEP door de overheid is gescreend.", "Het omgekeerde is waar: bij een PEP is het risico hoger en het onderzoek zwaarder."]]],
["Een zakelijke klant staat niet op een EU-sanctielijst, maar blijkt voor meer dan 50% eigendom te zijn van een gesanctioneerde persoon. Wat is volgens de Europese uitleg in beginsel juist?", [["Ook die onderneming valt in beginsel onder de bevriezing, vanwege eigendom of zeggenschap.", "Sancties zouden anders eenvoudig te omzeilen zijn; daarom geldt de bevriezing ook voor entiteiten die worden beheerst door een gesanctioneerde persoon."], ["De onderneming valt er niet onder, omdat alleen de namen op de lijst gelden.", "Een strikte toetsing op namen alleen maakt omzeiling via dochterondernemingen te eenvoudig."], ["De onderneming mag worden bediend zolang de verzekering geen betaling naar het buitenland vergt.", "Waar de betaling naartoe gaat is niet beslissend; het ter beschikking stellen van middelen is al verboden."], ["De onderneming valt er alleen onder als ook de bestuurders op de lijst staan.", "Het gaat om eigendom of zeggenschap van de gesanctioneerde persoon, niet om de vermelding van de bestuurders."]]],
["Waarom screenen schadeverzekeraars en schadebemiddelaars hun zakelijke klanten tegen sanctielijsten, ook als zij niet onder de Wwft vallen?", [["De sanctieregels gelden voor iedereen en financiële ondernemingen moeten integer werken.", "Wie geen Wwft-instelling is, moet de sanctieverboden toch naleven; screening is de manier om dat aantoonbaar te doen."], ["Omdat de Wwft voor zakelijke schadeverzekeringen boven een bepaalde jaarpremie toch van toepassing is.", "De Wwft wijst schadeverzekeraars en schadebemiddelaars niet aan; de plicht vloeit voort uit de sanctieregelgeving."], ["Omdat de Kamer van Koophandel dat verlangt voor de inschrijving van het kantoor.", "De KvK stelt geen screeningseisen aan financiële dienstverleners voor inschrijving."], ["Omdat de klant anders geen premie mag betalen via automatische incasso.", "Betaalwijze staat los van de sanctieplicht; het gaat om het verbod op dienstverlening aan gesanctioneerden."]]],
["Een exporteur vraagt een transportverzekering voor een zending naar een land waartegen de EU handelsbeperkingen heeft ingesteld. Wat moet de adviseur doen?", [["Nagaan of goederen, bestemming of betrokken partijen onder sancties vallen.", "Sanctieregels verbieden vaak niet alleen de handel zelf maar ook financiële diensten, waaronder verzekering, die die handel mogelijk maken."], ["De verzekering gewoon plaatsen, omdat de adviseur alleen voor de verzekering verantwoordelijk is en niet voor de handel.", "Juist het verlenen van verzekering kan onder het verbod op dienstverlening vallen."], ["De verzekering plaatsen met een hoger eigen risico, zodat de verzekeraar minder risico loopt.", "Een hoger eigen risico maakt een verboden dienst niet toegestaan."], ["Alleen het verzekerde bedrag verlagen tot onder de meldingsgrens van de FIU.", "Sanctieregels kennen geen ondergrens waaronder het verlenen van verboden diensten is toegestaan."]]]
];
